-- ============================================================================
-- CUSTOM CONFIGURABLE REWARD (ON/OFF + MANUAL PRIZE NAME) & BALANCED OPTIONS
-- ============================================================================
BEGIN;

-- 1. Add reward_enabled and reward_name to public.quiz_events
ALTER TABLE public.quiz_events
  ADD COLUMN IF NOT EXISTS reward_enabled boolean NOT NULL DEFAULT true;

ALTER TABLE public.quiz_events
  ADD COLUMN IF NOT EXISTS reward_name text NOT NULL DEFAULT 'Ajándék nyeremény';

-- 2. Compensate option lengths across all 98 quiz_questions so option length
--    follows a uniform ~1/3 shortest, ~1/3 middle, ~1/3 longest distribution
WITH balanced(question, options, correct_index, explanation, category) AS (
  VALUES
    ('Füstöt észlelsz a lakás folyosóján. Mi a legfontosabb?', '["Biztonságos útvonalon menekülni és a 112-t hívni.", "Előbb összeszedni az értéktárgyakat.", "Kinyitni minden ajtót, hogy kiszellőzzön."]'::jsonb, 0, 'Csak biztonságosan járható útvonalon menekülj. Sűrű füsttel telt lépcsőházba ne lépj be. Ha a kijutás veszélyes, csukd be az ajtót, hívd a 112-t, és jelezd, hol vagy; kövesd a tűzoltók utasításait.', 'altalanos'),
    ('Miért kell füstben lehetőleg alacsonyan haladni?', '["Mert a padlón mindig friss levegő van.", "A hő és a füst jellemzően felfelé száll.", "Mert négykézláb haladva sokkal kisebb az elbotlás és a sérülés veszélye."]'::jsonb, 1, 'Alacsonyabban általában kedvezőbbek a körülmények, de a füst ott is mérgező lehet.', 'altalanos'),
    ('Mit teszel, ha egy edényben ég a főzőolaj?', '["Azonnal hideg csapvizet öntesz rá, hogy lehűtsd a lángoló zsiradékot.", "Óvatosan megfogod konyharuhával, és kiviszed az égő edényt az erkélyre.", "Elzárod a hőt és fedővel letakarod; vizet tilos ráönteni."]'::jsonb, 2, 'Az égő olajra öntött víz súlyos lángfellobbanást okozhat. Veszély esetén távolodj el és hívd a 112-t.', 'altalanos'),
    ('Mit ellenőrzöl menekülés előtt egy zárt ajtónál?', '["Óvatosan ellenőrzöd, nem forró-e az ajtó; forró ajtót nem nyitsz ki.", "Azonnal feltéped, hogy gyorsabban kijuss.", "Vizet öntesz a kilincsre és belépsz."]'::jsonb, 0, 'A forró ajtót ne nyisd ki. A nem forró ajtó sem garantál füstmentes útvonalat. Ha nincs biztonságos kijárat, csukott ajtó mögül hívd a 112-t és jelezd a tartózkodási helyedet.', 'altalanos'),
    ('Mire jó az otthoni füstérzékelő?', '["Automatikusan elolt minden tüzet.", "Korán jelzi a füstöt, így időt ad a menekülésre.", "Teljesen kiváltja az otthoni menekülési tervet és a tűzoltó készüléket."]'::jsonb, 1, 'A korai figyelmeztetés életmentő lehet; az érzékelőt rendszeresen ellenőrizni kell.', 'altalanos'),
    ('Mit teszel, ha egy lítiumakkumulátoros eszköz füstöl és sziszeg?', '["Vastag kesztyűvel megfogod, és gyorsan bedobod a konyhai mosogatómedencébe.", "Közelről megvizsgálod a készüléket, és azonnal kihúzod belőle az akkumulátort.", "Eltávolodsz a füsttől, másokat is kiküldesz, és 112-t hívsz."]'::jsonb, 2, 'A sérült akkumulátor mérgező gázokat bocsáthat ki, és újra meggyulladhat.', 'altalanos'),
    ('Mit teszel, ha menekülés közben biztonságosan magad mögött becsukhatod az ajtót?', '["Becsukod, ezzel lassíthatod a tűz és a füst terjedését.", "Mindig nyitva hagyod a huzat miatt.", "Kiékeled teljesen nyitott helyzetben."]'::jsonb, 0, 'A zárt ajtó lassíthatja a tűz és a füst továbbterjedését.', 'altalanos'),
    ('Miért fontos a családi menekülési terv?', '["Csak a biztosító miatt.", "Mindenki előre tudja, merre juthat ki és hol találkoztok.", "Hogy vészhelyzetben pontosan beosszátok, ki melyik műszaki cikket menti ki."]'::jsonb, 1, 'A kijáratok és menekülési útvonalak előzetes ismerete csökkenti a bizonytalanságot.', 'altalanos'),
    ('Mit jelent az elzárkózás veszélyesanyag-felhő esetén?', '["Azonnal gépkocsiba ülni, és megpróbálni kikerülni a terjedő gázfelhőt.", "Minden nyílászárót kitárni, hogy a lakásban ne halmozódjon fel a gáz.", "Épületben maradni, bezárni az ablakokat és figyelni a híreket."]'::jsonb, 2, 'Veszélyesanyag-felhőnél a külső levegő bejutását kell csökkenteni a hatósági tájékoztatásnak megfelelően.', 'altalanos'),
    ('Mit kell tenni elzárkózáskor a külső levegőt beszívó klímával?', '["Kikapcsolni a külső levegőt bejuttató szellőztetést.", "Maximális fokozatra kapcsolni.", "Ablakot nyitni mellé."]'::jsonb, 0, 'A külső levegő bejuttatása szennyező anyagokat hozhat az épületbe.', 'altalanos'),
    ('Mi a különbség kitelepítés és kimenekítés között?', '["Nincs különbség, mindkettő ugyanaz.", "A kitelepítés előre tervezhető, a kimenekítés azonnali veszély miatti.", "A kitelepítés kizárólag önkéntes döntés, a kimenekítés pedig csak gyakorlat."]'::jsonb, 1, 'A polgári védelem külön kezeli az előre tervezhető és a sürgős lakóhelyelhagyást.', 'altalanos'),
    ('Melyik a legfontosabb összeállítás egy hosszabb kitelepítésre?', '["Nagy értékű szórakoztatóelektronikai eszközök, laptop és családi fotóalbumok.", "Többheti fagyasztott élelmiszerkészlet és nehéz konyhai kisgépek dobozban.", "Okmányok, gyógyszerek, víz, tartós étel, ruha és higiéniai cikkek."]'::jsonb, 2, 'A csomag legyen személyre szabott, könnyen hordozható, és igazodjon a hatóság tájékoztatásához.', 'altalanos'),
    ('Miért praktikus hátizsákban vinni a veszélyhelyzeti csomagot?', '["Szabadon maradnak a kezeid mozgáshoz és segítségnyújtáshoz.", "Mert minden hátizsák vízhatlan.", "Mert így több száz kilót vihetsz."]'::jsonb, 0, 'A könnyen hordozható csomag különösen fontos gyalogos mozgásnál.', 'altalanos'),
    ('Mit tegyél, ha hivatalosan elrendelik a kitelepítést?', '["Várj napokat további magyarázat nélkül.", "Kövesd a kijelölt útvonalat és a hatóságok utasításait.", "Indulj el önállóan földutakon, hogy elkerüld a főutakon kialakuló torlódást."]'::jsonb, 1, 'A szervezett mozgás és a tájékoztatás követése fontos az életvédelemhez.', 'altalanos'),
    ('Mire kell gondolni különösen a veszélyhelyzeti csomag tervezésekor?', '["Kizárólag a családfenntartó felnőttek eredeti okmányaira és bankkártyáira.", "Arra, hogy minden családtag pontosan egyforma felszerelést és ruhát kapjon.", "Gyermekek, idősek és tartós betegek egyéni szükségleteire."]'::jsonb, 2, 'A személyes szükségletek, gyógyszerek és segédeszközök nélkülözhetetlenek lehetnek.', 'altalanos'),
    ('Mikor szellőztess egy veszélyesanyag-felhő miatti elzárkózás után?', '["Ha a hatósági tájékoztatás szerint elmúlt a veszély.", "Az első szirénaszó alatt.", "Amikor a felhő a ház elé ér."]'::jsonb, 0, 'A szellőztetés idejét a helyi utasítások és a veszély elmúlása határozza meg.', 'altalanos'),
    ('Hosszabb áramszünet alatt mit tegyél a hűtőszekrény ajtajával?', '["Percenként nyitogasd.", "Lehetőleg tartsd végig csukva az ajtaját.", "Támaszd ki résnyire, hogy ne keletkezzen kellemetlen szag a hűtőtérben."]'::jsonb, 1, 'A hűtő ajtajának csukva tartása lassítja a felmelegedést. Egy előzőleg megfelelően hűtött, zárva tartott hűtő nagyjából 4 órán át tarthatja biztonságosan hidegen az ételt. Hosszabb kimaradásnál a hőmérséklet és az élelmiszer típusa alapján kell dönteni; kóstolással ne ellenőrizd a biztonságot.', 'altalanos'),
    ('Hol szabad működtetni egy benzinmotoros áramfejlesztőt?', '["Jól szellőző pincében vagy garázsban, ha a garázskaput félig nyitva hagyod.", "Fedett előtérben vagy zárt verandán, közvetlenül a nyitott ablak alá téve.", "Csak szabadban, az épülettől és nyílászáróktól legalább 6 méterre."]'::jsonb, 2, 'Az áramfejlesztő kipufogógáza életveszélyes szén-monoxidot tartalmaz. Garázsban vagy más zárt térben nyitott ajtó mellett sem működtethető. A gyártó ennél nagyobb távolságot is előírhat.', 'altalanos'),
    ('Mivel NEM szabad fűteni áramszünetkor?', '["Beltérben használt kerti grillsütővel vagy gáztűzhellyel.", "Biztonságosan alkalmazott, erre tervezett fűtőberendezéssel.", "Megfelelő meleg ruházattal és takaróval."]'::jsonb, 0, 'Az égéstermékek és a szén-monoxid mérgezést okozhatnak.', 'altalanos'),
    ('Erős gázszagot észlelsz a lakásban. Mi a biztonságos reakció?', '["Kapcsold fel sorban a villanyokat.", "Ne kapcsolj villanyt; zárd el a gázt, menj ki és kintről hívj segítséget.", "Indítsd el a konyhai páraelszívót maximális fokozaton az ablak kinyitása mellett."]'::jsonb, 1, 'Ne működtess kapcsolót, ne húzz ki dugót, és ne telefonálj a gázszagú térben. A gázt csak saját veszélyeztetésed nélkül zárd el. Hagyd el a helyet, és biztonságos távolságból hívd a gázszolgáltatót vagy közvetlen veszélyben a 112-t.', 'altalanos'),
    ('Miért kell áramszünetkor a fontos egészségügyi eszközökre is tervezni?', '["Mert minden otthoni gyógyászati berendezés legalább egy hétig bírja akkumulátorról.", "Mert áramszünet idején az elektromos orvosi készülékek maguktól újraindulnak.", "Egyes orvosi eszközök és gyógyszerek áramot vagy hűtést igényelnek."]'::jsonb, 2, 'Életfontosságú eszköz esetén előre kidolgozott tartalék áramellátási és ellátási terv szükséges.', 'altalanos'),
    ('Miért érdemes a nem életfenntartó, érzékeny elektronikus készülékeket kihúzni áramszünetben?', '["A visszatérő áramellátáskor fellépő túlfeszültség elleni védelem miatt.", "Hogy gyorsabban jöjjön vissza az áram.", "Mert a dugó mindig felrobban áram nélkül."]'::jsonb, 0, 'A hálózat visszakapcsolásakor fellépő túlfeszültség károsíthatja az érzékeny berendezéseket. Orvosi, életfenntartó eszközöknél az előre egyeztetett ellátási tervet kövesd.', 'altalanos'),
    ('A szén-monoxid-érzékelő CO-veszélyjelzést ad. Mit teszel?', '["Biztosan csak lemerült a telefon.", "Azonnal hagyd el az épületet, és kintről kérj segítséget.", "Kapcsold be a fürdőszobai elszívóventilátort, és feküdj le pihenni a szobában."]'::jsonb, 1, 'A CO színtelen, szagtalan és életveszélyes. Menj biztonságos helyre, kérj segítséget, és ne térj vissza a veszélyes térbe hibát keresni. Az elem- vagy készülékhiba-jelzéseket a gyártói útmutató különíti el a CO-riasztástól.', 'altalanos'),
    ('Mit érdemes kéznél tartani váratlan áramszünetre?', '["Több szál égő viaszgyertyát minden szobában, éjszakára is égve hagyva.", "Kizárólag vezetékes asztali telefont és hálózati 230 voltos halogén reflektorokat.", "Feltöltött telefont, powerbankot, elemlámpát és elemes rádiót."]'::jsonb, 2, 'Az önálló energiaforrás és a hiteles tájékoztatás elérése alapvető.', 'altalanos'),
    ('Nagy hóban elakadsz egy elhagyatott úton. Mi az elsődleges?', '["Segítséget kérsz és megadod a helyzeted; ha a járműnél nem fenyeget közvetlen veszély, ott maradsz védett helyen.", "Indulj el azonnal gyalogosan a szántóföldön át a legközelebbi település irányába.", "Kapcsold le az összes világítást, és zárd el teljesen a levegő utánpótlását."]'::jsonb, 0, 'Erős hóviharban a jármű védelmet adhat és könnyebben megtalálható; közvetlen veszély esetén más döntés szükséges.', 'altalanos'),
    ('Miért kell a kipufogót szabaddá tenni, mielőtt a havas úton járatod a motort?', '["Hogy hangosabban szóljon a motor.", "Az utastérbe jutó szén-monoxid-mérgezés elkerüléséért.", "Hogy a forró kipufogógáz ne olvassza meg a hátsó lökhárító műanyag elemeit."]'::jsonb, 1, 'A hó eltömítheti a kipufogót, és a kipufogógáz visszajuthat a járműbe.', 'altalanos'),
    ('Melyik felszereléscsomag a leghasznosabb hosszú téli útra?', '["Csak egy műanyag jégkaparó, páramentesítő kendő és nyári szélvédőmosó folyadék.", "Pótkerék helyett defektjavító spray, napszemüveg és vékony esőkabát a csomagtérben.", "Takaró, meleg ruha, víz, étel, lámpa, hólapát és töltött telefon."]'::jsonb, 2, 'A magyar rendőrség is hangsúlyozza az úti és téli vészfelszerelés fontosságát.', 'altalanos'),
    ('Melyikre érdemes figyelni téli indulás előtt?', '["Időjárás, útviszonyok, abroncsok, akkumulátor és világítás.", "Csak az autórádió hangerőre.", "Csak az üléskárpitra."]'::jsonb, 0, 'A technikai állapot és a tájékozódás csökkentheti az elakadási és baleseti kockázatot.', 'altalanos'),
    ('Hóviharban elakadt autót látsz. Mit tegyél?', '["Azonnal megállsz az úttest közepén.", "Biztonságos helyről mérd fel a helyzetet, szükség esetén hívd a 112-t.", "Hajts tovább megállás és bejelentés nélkül, mert télen ez mindennapos jelenség."]'::jsonb, 1, 'Saját biztonságod elsődleges; a bajba jutók helyét és állapotát pontosan jelezd a segélyhívón.', 'altalanos'),
    ('Meghibásodás miatt biztonságosan megálltál az út szélén. Mi segítheti a láthatóságot?', '["A teljes világítás lekapcsolása, hogy ne merüljön le idő előtt az akkumulátor.", "A csomagtérajtó felnyitása vészvillogó és elakadásjelző háromszög használata nélkül.", "Vészvillogó, láthatósági mellény és elakadásjelző háromszög."]'::jsonb, 2, 'A vészvillogó és a körülményeknek megfelelő elakadásjelzés figyelmeztethet másokat. A jelzés kihelyezése ne sodorjon új veszélybe. Autópályán a járműben várakozás helyett a szalagkorláton kívüli védett hely lehet szükséges; kövesd a helyszíni útmutatást.', 'altalanos'),
    ('Elakadás közben hogyan csökkentheted a kihűlés kockázatát?', '["Száraz, réteges ruházattal, takaróval és szükség esetén szakszerű segítségkéréssel.", "Tömény szeszes ital fogyasztásával, mert az tartósan megemeli a belső testhőt.", "Folyamatos ki-be szállással és a hóban végzett intenzív futással az autó körül."]'::jsonb, 0, 'A kihűlés megelőzéséhez a száraz ruházat és a hőveszteség csökkentése fontos.', 'altalanos'),
    ('Hóviharban, biztonságos helyen várakozva mi igaz a fűtés céljából járatott motorra?', '["Órákon át folyamatosan járhat, zárt ablakok mellett.", "Csak szakaszosan járjon, szabad kipufogó és résnyire nyitott ablak mellett.", "Csak belső levegőkeringtetéssel szabad járatni, a kipufogót nem kell ellenőrizni."]'::jsonb, 1, 'A hóviharban várakozó járműnél az NWS rövid, szakaszos motorjáratást javasol, például óránként körülbelül 10 percet. A kipufogó legyen szabad, és biztosítani kell a szellőzést. Ez nem általános biztonsági garancia: CO-kockázat vagy más közvetlen veszély esetén kérj sürgős segítséget.', 'altalanos'),
    ('Mit kell tenni, ha lakott területen hirtelen, rendkívül erős szélvihar (orkán) tör ki az utcán?', '["Állj be egy terebélyes fa vagy magas reklámtábla alá, amíg elvonul a széllökés.", "Kerüld a fákat és vezetékeket, menj mielőbb stabil épületbe.", "Kapaszkodj meg egy utcai villanyoszlopban vagy ideiglenes építési állványzatban."]'::jsonb, 1, 'Kerüld a leszakadó ágakat és tárgyakat. Ne állj meg sérült épületrész alatt; keress biztonságos menedéket.', 'altalanos'),
    ('Mit jelent a HungaroMet piros figyelmeztetése magas középhőmérséklet miatt?', '["Csak mérsékelt nyári felmelegedést jelez, elegendő szalmakalapot viselni délben.", "Kiemelten veszélyes hőséget jelez; csökkenteni kell a megterhelést, hűvös helyet keresni és követni a hivatalos tájékoztatást.", "Kizárólag a mezőgazdasági öntözőrendszerek üzemeltetőinek szóló technikai jelzés."]'::jsonb, 1, 'A meteorológiai figyelmeztetés és az egészségügyi hőségriasztás külön rendszer. Nem azonos a szociális ellátás vörös kódjával.', 'altalanos'),
    ('Hogyan kell védekezni villámárvizek (hirtelen lezúduló nagy esők miatti áradások) esetén?', '["Le kell menni a mélygarázsba megnézni az autót.", "Menj magasabb terepre, és kerüld az aluljárókat, pincéket.", "Állj be gépkocsival a legmélyebb közúti aluljáróba, amíg a felhőszakadás eláll."]'::jsonb, 1, 'Minél gyorsabban el kell jutni a magasabban fekvő, biztonságos területekre, és kerülni kell az aluljárókat, pincéket.', 'altalanos'),
    ('Mi a teendő, ha autózás közben hatalmas jégeső lep meg?', '["Gyorsíts fel, hogy minél rövidebb ideig tartózkodj a jégveréssel érintett zónában.", "Lassíts, és állj meg biztonságos helyen, fáktól távol.", "Állj meg hirtelen a belső sávban vagy közvetlenül egy út menti fasor árnyékában."]'::jsonb, 1, 'Ne állj meg forgalmi sávban vagy híd alatt úgy, hogy másokat veszélyeztetsz. Maradj a járműben, amíg biztonságosan tovább lehet indulni.', 'altalanos'),
    ('Mit jelent a másodfokú (narancs) riasztás zivatar és felhőszakadás esetén?', '["Csendes, veszélytelen nyári záport jelent, amely nem igényel semmilyen óvintézkedést.", "Fokozott veszélyt jelez; figyelni kell a friss előrejelzéseket és felkészülni a heves időjárás hatásaira.", "Kötelező érvényű országos kijárási és közlekedési tilalom automatikus életbelépését."]'::jsonb, 1, 'A narancssárga jelzés veszélyes időjárást jelez, de önmagában nem jelent kijárási tilalmat.', 'altalanos'),
    ('Hová menj, ha túrázás közben meghallod a mennydörgést?', '["Magas fa teteje vagy egy magányos fa töve.", "Menj stabil épületbe vagy zárt, keménytetős gépkocsiba.", "Maradj a hegytetőn felállított túrasátorban a fém sátorrudak mellé kuporodva."]'::jsonb, 1, 'Szabadban nincs villámbiztos hely. A guggolás nem teszi biztonságossá a helyzetet.', 'altalanos'),
    ('Mi az elsődleges veszélyforrás egy tartós, heves téli hófúvás (blizzard) során?', '["A hirtelen megemelkedő légnedvesség miatti nyári hőpangás és napszúrás.", "A kihűlés, az utakon való elakadás és az áramkimaradás.", "A talajvíz azonnali felforrósodása és a felszíni UV-sugárzás megugrása."]'::jsonb, 1, 'A kihűlés (hipotermia), a magányos utakon elakadás és a fűtés/áramkimaradás.', 'altalanos'),
    ('Mit kell tenni, ha lakóhelyeden hirtelen bekövetkező, extrém vihar miatt elmegy az áram és a fűtés?', '["Szellőztess ki egyszerre minden szobát, hogy kiegyenlítsd a külső-belső hőmérsékletet.", "Meleg ruhát ölteni, lezárni a kihűlő helyiségeket, és bekapcsolni az elemes rádiót a friss információkért.", "Kapcsold be a konyhai gázsütőt nyitott ajtóval, hogy befűtse az egész lakást."]'::jsonb, 1, 'Öltözz melegen, tartsd meg a hőt és figyeld a hivatalos híreket. Beltérben ne használj kültéri égésű eszközt vagy áramfejlesztőt.', 'altalanos'),
    ('Mit jelez a meteorológiában a ''szupercella'' kifejezés?', '["Egy óriási felhőkarcolót Budapesten.", "Forgó feláramlású heves zivatar; nagy jégesőt és orkánt okozhat.", "A meteorológiai radarállomások legújabb generációs napelemes mérőegysége."]'::jsonb, 1, 'Nem minden szupercella okoz tornádót. A veszélyjelzéseket kell követni, nem egy felhő látványából dönteni.', 'altalanos'),
    ('Mi a teendő erdőtűz esetén, ha észreveszed a lángokat a kirándulás során?', '["Futva indulj el a széllel megegyező irányba a sűrű fenyves belseje felé.", "Távolodj el biztonságos irányba, hívd a 112-t és kövesd az utasítást.", "Menj egészen közel a lángokhoz fotót készíteni, mielőtt bejelentenéd a tüzet."]'::jsonb, 1, 'A szél és a terep gyorsan változtathatja a tűz terjedését; egyetlen általános irányszabály nem garantál menekülést.', 'altalanos'),
    ('Mely tünetek utalhatnak hőgutára?', '["Enyhe torokkaparás, tüsszögés és normális, 36,5 °C körüli testhőmérséklet.", "Nagyon magas testhőmérséklet, zavartság, rossz koordináció, eszméletvesztés; a bőr lehet száraz vagy verejtékes.", "Fokozott éhségérzet, élénk koncentráció és lassú, nyugodt szívverés pihenéskor."]'::jsonb, 1, 'Hőguta gyanújánál azonnali segélyhívás és hűtés szükséges. Ne várj arra, hogy magától rendeződjön.', 'altalanos'),
    ('Mi a helyes döntés, ha elöntött útszakaszhoz érsz autóval?', '["Maradj benne üvöltve, amíg el nem apad.", "Ne hajts a vízbe; fordulj vissza és keress biztonságos kerülőutat.", "Kövesd szorosan az előtted haladó teherautót a mély vízzel borított útszakaszon."]'::jsonb, 1, 'Ne alapozd a biztonságot a kerék vagy küszöb magasságára. A víz mélysége, sodrása és az út állapota kívülről nem ítélhető meg.', 'altalanos'),
    ('Hogyan védekezzünk az UV-sugárzás ellen nyári napokon szabadtéren?', '["Déli órákban vizes bőrrel napozz árnyék nélkül, mert a víz kiszűri a sugarakat.", "Keress árnyékot, viselj fejfedőt, napszemüveget és használj naptejet.", "Csak borult időben használj szemvédelmet, kánikulában kerüld a folyadékpótlást."]'::jsonb, 1, 'Árnyék, megfelelő ruházat, fejfedő, napszemüveg és megfelelő fényvédő; erős UV idején kerülni kell a tűző napot.', 'altalanos'),
    ('Mi a teendő szén-monoxid mérgezés gyanúja esetén otthon?', '["Zárd be az ablakokat, feküdj le pihenni, és várj, amíg a fejfájás magától elmúlik.", "Azonnal kijutni a friss levegőre, másokat is figyelmeztetni és biztonságos helyről 112-t hívni.", "Gyújts meg egy öngyújtót a kazán mellett, hogy ellenőrizd az oxigénszintet."]'::jsonb, 1, 'Ne késleltesd a kijutást a berendezés keresésével vagy szellőztetéssel, és ne menj vissza a veszélyes térbe.', 'altalanos'),
    ('Mi a lakosság feladata súlyos időjárási veszélyjelzéskor?', '["Bezárja az összes boltot és bankot.", "Figyelni a hivatalos híreket és kerülni a felesleges utazást.", "Kimenni a szabadba megfigyelni és közelről videózni az érkező viharfrontot."]'::jsonb, 1, 'A meteorológiai piros jelzés és a szociális vörös kód nem azonos. Az intézkedések az adott eseménytől függnek.', 'altalanos'),
    ('Mikor kell figyelni a heves zivatarok veszélyére Magyarországon?', '["Kizárólag a téli fagyos hónapokban, december közepe és február vége között.", "Főként a meleg évszakban, de mindig a veszélyjelzés alapján.", "Csak páros évek tavaszán, amikor a folyók vízállása tartósan alacsony marad."]'::jsonb, 1, 'A naptári hónap önmagában nem zárja ki a heves zivatar lehetőségét.', 'altalanos'),
    ('Melyik tünet utalhat kezdődő kihűlésre?', '["Hirtelen kipirult, forró arcbőr, bőséges izzadás és szokatlanul élénk beszéd.", "Remegés, hideg bőr és romló kézügyesség; súlyosbodáskor zavartság és beszédzavar is jelentkezhet.", "Erős szomjúságérzet, szapora pislogás és a testhőmérséklet gyors emelkedése."]'::jsonb, 1, 'A hipotermia kihűlést jelent, nem eleve halált. Súlyos gyanú esetén 112 és kíméletes védelem a további hővesztéstől.', 'altalanos'),
    ('Mi a helyes eljárás, ha fagyos időben beszakad valaki alatt a jég a tavon?', '["Rohanva odafutni a lék szélére.", "Hívd a 112-t, és a partról nyújts biztonságos segítséget.", "Dobálj nehéz köveket a jégre a bajbajutott mellé, hogy nagyobb legyen a nyílás."]'::jsonb, 1, 'A hason csúszás sem garantálja a jég teherbírását. Ne válj második áldozattá.', 'altalanos'),
    ('Mi az a ''száraz villám''?', '["Olyan különleges téli villámlás, amely csak befagyott tavak felett jöhet létre.", "Villámlás, amikor a csapadék nem éri el a felszínt; tüzet okozhat.", "Elektromos kisülés, amely teljesen hangtalan és soha nem jelent tűzveszélyt."]'::jsonb, 1, 'Az eső hiánya nem zárja ki a villámcsapást. Az erdőtüzek okai területenként eltérnek; nem állítjuk, hogy mindenütt ez a fő ok.', 'altalanos'),
    ('Mit kell tenni erős földrengés alatt zárt térben?', '["Azonnal szaladj ki az erkélyre vagy hívd a liftet, hogy lejuss a földszintre.", "Leguggolni, fedezékbe húzódni és kapaszkodni; védeni a fejet, kerülni az ablakokat és a liftet.", "Állj közvetlenül a legnagyobb üvegablak vagy egy magas könyvespolc elé."]'::jsonb, 1, 'Stabil asztal alatt védd a fejed, és kapaszkodj. Ne rohanj a rázkódás közben a kijárathoz.', 'altalanos'),
    ('Mit tartalmazzon egy jól összeállított 72 órás vészhelyzeti hátizsák (Bug-out bag)?', '["Csak divatos ruhákat és egy tabletet.", "Vizet, tartós ételt, elsősegélyt, lámpát, rádiót és gyógyszert.", "Friss tejet, fagyasztott húst és hálózati hosszabbítót elemek és ivóvíz nélkül."]'::jsonb, 1, 'Ivóvizet, tartós élelmiszert, elsősegélycsomagot, zseblámpát, elemes rádiót, iratmásolatot és gyógyszereket.', 'altalanos'),
    ('Hogyan kell vízhez jutni a vadonban, ha kifogytál az ivóvízből?', '["Igyál bátran bármilyen erdei pocsolyából, ha a víz szabad szemmel átlátszónak tűnik.", "Keress biztonságos forrást; a természetes vizet mindig kezeld.", "Fogyassz sós vizet vagy olvasztott útszéli havat szűrés és forralás nélkül."]'::jsonb, 1, 'A forralás a kórokozók ellen segíthet, de a vegyi szennyeződést nem távolítja el. Nem minden szűrő távolít el minden kórokozót.', 'altalanos'),
    ('Mit tegyél jelentős külső vérzés esetén, ha a helyszín biztonságos?', '["Hagyd szabadon vérezni a sebet, hogy a szennyeződés magától kimosódjon belőle.", "Erős, közvetlen nyomást gyakorolni a sebre tiszta kötszerrel, segítséget hívni és követni a 112 utasításait.", "Húzd ki azonnal a sebbe ékelődött idegentestet, majd szórj hintőport a nyílásba."]'::jsonb, 1, 'Az elsődleges cél a vérveszteség csökkentése. Beékelődött tárgyat nem húzunk ki; körülötte alkalmazunk nyomást.', 'altalanos'),
    ('Hogyan jelölheted meg a tartózkodási helyedet, ha segítséget vársz a mentőktől az erdőben?', '["Elégetni az összes fát.", "Jelezz síppal, lámpával vagy élénk ruhával, és hívd a 112-t.", "Bújj el mozdulatlanul egy sűrű bokor alatt sötét ruhában, és kapcsold ki a telefont."]'::jsonb, 1, 'Jelzés céljából se gyújts tüzet, ha az veszélyes vagy tiltott; a fény és hang biztonságosabb jelzőeszköz lehet.', 'altalanos'),
    ('Mi a helyes öltözködési elv túrázáskor vagy hűvös időben (a hagyma-elv)?', '["Egyetlen vastag pamutpóló és rávett nehéz télikabát köztes szigetelőréteg nélkül.", "Réteges öltözék: izzadságelvezető alap, hőtartó közép és szélálló héj.", "Szoros, nem szellőző műanyag esőruha közvetlenül a meztelen bőrre felvéve."]'::jsonb, 1, 'Réteges öltözködés: nedvességelvezető alsó réteg, hőtartó középső réteg és szél-/vízálló külső héj.', 'altalanos'),
    ('Melyik eszköz a leghasznosabb tájékozódáshoz, ha lemerült a telefonod GPS-e?', '["Egy kockás füzet.", "Analóg tájoló (kompassz) és papíralapú térkép.", "Egy darab faág."]'::jsonb, 1, 'Analóg tájoló (kompassz) és papíralapú térkép.', 'altalanos'),
    ('Hány lakástűz köthető évente Magyarországon az adventi koszorúkhoz a katasztrófavédelem adatai szerint?', '["Kevesebb mint 5", "Átlagosan évi 50–70 lakástűz.", "Több mint 600 súlyos lakástűz indul ki koszorúkból minden decemberben."]'::jsonb, 1, 'Évente átlagosan 50–70 lakástűz indul ki adventi koszorúról, jellemzően felügyelet nélkül hagyott gyertya vagy hiányzó alátét miatt.', 'advent'),
    ('Mire kell mindenképpen figyelni az adventi koszorú elhelyezésekor?', '["Közvetlenül a csipkefüggöny mellé, száraz fenyőágakkal körberakva tegyük le.", "Tűzálló alátétre helyezzük, és legyen alatta fém gyertyatüske.", "Vékony dekorációs műanyag tálcára vagy fonott vesszőkosárba állítsuk tüske nélkül."]'::jsonb, 1, 'A leégő kanóc átégetheti a száraz koszorúalapot; a fém gyertyatartó tüske és a nem éghető alátét megakadályozza a tűz továbbterjedését.', 'advent'),
    ('Mi a legfontosabb szabály, ha elhagyod azt a helyiséget, ahol ég az adventi gyertya?', '["Csak akkor kell elfújni, ha 1 óránál tovább vagy távol", "Mindig fújd el a gyertyát, még akkor is, ha csak néhány percre hagyod el a szobát.", "Elég, ha becsukod a szobaajtót"]'::jsonb, 1, 'Egy kiszáradt koszorú másodpercek alatt lángra kaphat, ezért nyílt lángot soha nem szabad őrizetlenül hagyni.', 'advent'),
    ('Milyen távolságra kell elhelyezni az égő gyertyát a függönytől, terítőtől vagy más éghető anyagtól?', '["Legalább 10 cm-re", "Legalább 50–100 cm távolságra minden éghető anyagtól.", "Nincs szükség semmilyen védőtávolságra, ha egy pohár vizet teszel az asztalra."]'::jsonb, 1, 'A huzat vagy a levegő áramlása könnyen a lángba sodorhatja a függönyt, a papírszalvétát vagy a száraz gallyakat.', 'advent'),
    ('Mit tegyél, ha a kiszáradt adventi koszorú vagy a terítő meggyullad?', '["Próbáld meg puszta kézzel felkapni, és kiszaladni az égő koszorúval a lépcsőházba.", "Takard le vastag nedves textíliával, vagy használj tűzoltó készüléket.", "Tárd ki azonnal az összes ablakot, hogy az erős huzat kifújja a szobából a füstöt."]'::jsonb, 1, 'A letakarás elzárja az oxigént a tűztől, míg az ablaknyitás huzatot kelt és táplálja a lángokat.', 'advent'),
    ('Mire figyelj a karácsonyi fényfüzérek vásárlásakor és használatakor?', '["Bármilyen jelöletlen beltéri égősort nyugodtan felszerelhetsz a havas kerti fákra is.", "Csak magyar nyelvű használati utasítással és CE jelöléssel ellátott terméket vegyél, és éjszakára húzd ki", "A megsérült szigetelésű vezetékeket elegendő átlátszó irodai ragasztószalaggal betekerni."]'::jsonb, 1, 'A hibás, túlmelegedő égősorok zárlatot okoznak; beltéri fényfüzért pedig szigorúan tilos kültéren használni.', 'advent'),
    ('Mi a biztonságos megoldás kisgyermekes vagy háziállatos háztartásban gyertyagyújtás helyett?', '["Magas polcra tett hagyományos teamécses", "LED-es elemes gyertya vagy mécses használata.", "Illatgyertya nyitott tálkában a szőnyegre vagy az alacsony dohányzóasztalra helyezve."]'::jsonb, 1, 'Egy kíváncsi háziállat egyetlen mozdulattal leverheti az égő gyertyát – a LED-es gyertya teljesen tűzbiztos.', 'advent'),
    ('Használható-e csillagszóró a karácsonyfán vagy az adventi koszorú felett?', '["Igen, nyugodtan felakasztható a fára, ha előtte befújjuk a tűleveleket hajlakkal.", "Nem, az 1000–1600 °C-os szikrák azonnal lángra lobbantják a száraz fát.", "Igen, egyszerre akár több csillagszóró is meggyújtható a száraz fenyőágak között."]'::jsonb, 1, 'A csillagszóró szikrája rendkívül forró, a száraz fenyőág pedig szinte robbanásszerűen, másodpercek alatt lángra kap tőle.', 'advent'),
    ('Hogyan kell elhelyezni a karácsonyfát a lakásban tűzvédelmi szempontból?', '["Közvetlenül a forró radiátor, cserépkályha vagy a bejárati ajtó elé állítva.", "Hőforrástól (kályhától, radiátortól) és menekülési útvonaltól (bejárati ajtótól) távol", "Az egyetlen kijárat elé helyezve, több egymásba dugott elosztóval körbevezetve."]'::jsonb, 1, 'A fűtőtestek kiszárítják a fát, ami így sokkal gyúlékonyabbá válik; az ajtó közelében álló égő fa pedig elzárhatja a menekülési utat.', 'advent'),
    ('Mit ne tegyél SOHA, ha a konyhában az ünnepi sütés-főzés közben meggyullad a forró olaj a serpenyőben?', '["Soha ne önts rá vizet!", "Ne tegyél rá fém fedőt", "Ne zárd el alatta a gázt vagy a főzőlapot, amíg a láng magától el nem alszik!"]'::jsonb, 0, 'A víz az égő olajba öntve azonnal gőzzé válik, és hatalmas tűzgömbként szétveti a lángoló zsiradékot – fedővel kell elfojtani.', 'advent'),
    ('Mit jelent a meteorológiai szolgálat által kiadott „vörös” (harmadfokú) riasztás hófúvás vagy ónos eső esetén?', '["Kizárólag a 7,5 tonna feletti tehergépjárművek számára korlátozza az előzést az utakon.", "Halaszthatatlan eseten kívül senki ne induljon útnak: életveszélyes.", "Csak annyit jelent, hogy a hegyvidéki szakaszokon ajánlott a téli szélvédőmosó használata."]'::jsonb, 1, 'A legmagasabb, piros fokozatú riasztásnál a közlekedési infrastruktúra megbénulhat, és az elakadt járművek mentése is akadályozott.', 'teli_idojaras'),
    ('Mit tegyél elsőként, ha autóddal hótorlaszban elakadsz a lakott területen kívül?', '["Indulj el gyalog a hóviharban a legközelebbi falu felé", "Maradj a járműben, kapcsold be a vészvillogót, és hívd a 112-t", "Engedd le a gumiabroncsok nyomását"]'::jsonb, 1, 'A jármű védelmet nyújt a szél és a kihűlés ellen, és a mentőegységek is sokkal könnyebben megtalálják, mint egy gyalogost a hóviharban.', 'teli_idojaras'),
    ('Mire kell kiemelten figyelni, ha a hóban elakadt autóban járatod a motort a fűtés miatt?', '["Semmire, a modern autók teljesen biztonságosak", "Tisztítsd meg a kipufogót a hótól, és résnyire húzd le az ablakot.", "Zárd fel szorosan az összes ablakot, és kapcsold be folyamatosan a belső keringtetést."]'::jsonb, 1, 'A hóval eltömődött kipufogóból a szén-monoxid visszaáramlik az utastérbe, ami percek alatt halálos mérgezést okozhat.', 'teli_idojaras'),
    ('Milyen alapvető felszerelést érdemes télen az autóban tartani egy váratlan elakadás esetére?', '["Elegendő egy vékony műanyag jégkaparó és egy kis flakon illatosított utastér-tisztító.", "Meleg takarót, pót-ruhát, lámpát, powerbankot, vizet és élelmet.", "Csak nyári keréknyomásmérőt, napellenzőt és egy üres műanyag kannát a csomagtartóban."]'::jsonb, 1, 'Hótorlasz vagy útlezárás esetén akár órákat is várakozni kell a mentésre, amikor a testhő megtartása és a telefon feltöltöttsége életmentő.', 'teli_idojaras'),
    ('Mit jelent a szociális ellátórendszerben elrendelt „Vörös kód”?', '["Országos tervszerű áramszünetet jelent a nagyfeszültségű távvezetékek jegesedése miatt.", "Extrém hideg miatt minden szociális intézmény köteles befogadni a hajléktalan vagy bajba jutott embereket", "Teljes körű tüzelési tilalmat rendel el a családi házak vegyestüzelésű kazánjaira."]'::jsonb, 1, 'A Vörös kód figyelmezteti a társadalmat a rendkívüli hidegre, és kötelezővé teszi a krízisellátást minden fenntartó számára.', 'teli_idojaras'),
    ('Mi a helyes teendő, ha közterületen egy kihűlés veszélyének kitett, magatehetetlen embert látsz?', '["Adj neki alkoholt, hogy átmelegedjen", "Hívd a 112-t, és maradj mellette a mentők kiérkezéséig.", "Dörzsöld be erősen fagyott hóval az arcát és a végtagjait a keringés serkentésére."]'::jsonb, 1, 'Az alkohol tágítja a perifériás ereket, így valójában gyorsítja a test hővesztését és a kihűlést.', 'teli_idojaras'),
    ('Mi a legfontosabb szabály, ha befagyott természetes víz (tó, folyó, csatorna) jegére lépnél?', '["Ha a part mentén 2–3 centiméteresnek látszik a jégréteg, bárhol biztonságosan korcsolyázhatsz.", "Csak kijelölt helyen és nappal menj jégre; folyóvíz jegére soha.", "Minél nagyobb csoportban, szorosan egymás mellett haladva menj rá a természetes folyóvízre."]'::jsonb, 1, 'A folyók és csatornák jege az áramlás miatt kiszámíthatatlanul vékonyodik, és a jég alá szorulás szinte azonnal végzetes.', 'teli_idojaras'),
    ('Mit tegyél, ha beszakad alattad a jég?', '["Kapálózz erőteljesen függőleges testhelyzetben, és könyökkel törd magad előtt a vékony jeget.", "Hasalj rá a jégre, terjeszd szét a súlyodat, és hason csúszva kússz vissza arra, amerről jöttél", "Merülj a jégpáncél alá, és a víz alatt úszva próbálj meg egy másik kijáratot keresni."]'::jsonb, 1, 'A jég széle letörik, ha függőlegesen próbálsz kimászni; hason fekve oszlik el a testsúly, és arra a legbiztosabb a jég, amerre korábban elbírt.', 'teli_idojaras'),
    ('Hogyan közlekedj gyalogosan és autóval ónos eső idején?', '["A megszokott sebességgel, csak nagyobb követési távolsággal", "Csak végszükség esetén indulj el, rendkívül lassan és óvatosan.", "Kerékpárral vagy elektromos rollerrel közlekedj, mert két keréken kisebb a megcsúszás esélye."]'::jsonb, 1, 'Az ónos eső azonnal tükörjéggé fagy a hideg burkolaton, amin a járművek irányíthatatlanná válnak.', 'teli_idojaras'),
    ('Hogyan előzheted meg a vízvezetékek elfagyását fűtetlen nyaralóban vagy melléképületben?', '["Hagyj felkapcsolva egy kis teljesítményű LED-lámpát a pincében egész télre fűtés helyett.", "Zárd el a főcsapot, és víztelenítsd a teljes csőhálózatot és a bojlert.", "Tekerd körbe vékony selyempapírral a kerti csapot, miközben nyomás alatt hagyod a rendszert."]'::jsonb, 1, 'A megfagyó víz térfogata megnő, így szétrepeszti a csöveket és a szerelvényeket, ami olvadáskor súlyos vízkárt okoz.', 'teli_idojaras'),
    ('Mi a különbség a hagyományos folyami árvíz és a villámárvíz között?', '["Csak elnevezésbeli különbség van, mindkettő hetek alatt, lassan emelkedő síkvidéki áradás.", "A villámárvíz heves felhőszakadás után percek vagy órák alatt, előjelzés nélkül csap le, főleg domb- és hegyvidéken", "A villámárvíz kizárólag a téli hóolvadáskor, nagy folyók alsó szakaszán alakulhat ki."]'::jsonb, 1, 'A villámárvizek rendkívül gyors lefolyásúak és nagy sodrásúak, ezért a menekülésre és a védekezésre csupán percek állnak rendelkezésre.', 'arviz_belviz'),
    ('Milyen magasságú vízborítás képes már elsodorni egy felnőtt embert áramló árvíz esetén?', '["Csak a mellkasig érő víz", "Már 15–20 cm-es gyors folyású víz is elsodorhat.", "Áramló vízben csak akkor veszélyes a gyaloglás, ha a vízszint meghaladja a vállmagasságot."]'::jsonb, 1, 'A mozgó víztömeg ereje hatalmas: már bokáig-lábszárközépig érő sodrás is könnyen elsodor egy felnőttet.', 'arviz_belviz'),
    ('Mikor válik irányíthatatlanná és sodródik el egy személyautó elárasztott útszakaszon?', '["Csak akkor úszik fel az autó, ha a vízszint már teljesen ellepi a szélvédőt és a motorháztetőt.", "Már 30–50 cm-es áramló víz felúsztatja és elsodorja az autót.", "Egy személygépkocsi több mint egytonnás tömege miatt semmilyen áradásban nem sodródhat el."]'::jsonb, 1, 'Soha ne hajts be elárasztott útszakaszra vagy aluljáróba: az úttest alámosódhat, a felhajtóerő pedig felemeli az autót.', 'arviz_belviz'),
    ('Mi az elsődleges teendő az épület közműveivel, ha az ingatlant árvíz vagy betörő belvíz fenyegeti?', '["Minden lámpát fel kell kapcsolni, hogy jól lássunk", "Áramtalanítani kell a főkapcsolónál, valamint el kell zárni a gáz- és vízcsapot", "Be kell kapcsolni a szivattyút a víz alatt álló pincében"]'::jsonb, 1, 'A víz és az elektromosság találkozása életveszélyes áramütést okoz; áramtalanítás előtt tilos a vízbe lépni.', 'arviz_belviz'),
    ('Hogyan kell helyesen rakni a homokzsákokat védmű építésekor?', '["Függőlegesen egymás mellé állítva", "Kötésben (mint a téglafalat), kb. kétharmadig töltve, a szájukat behajtva és megtaposva.", "Töltsd meg őket színültig száraz kaviccsal, és kötözés nélkül dobáld egymás tetejére."]'::jsonb, 1, 'A kötésben rakott, kb. kétharmadig töltött és jól tömörített zsákok zárnak vízzáróan, és nem csúsznak szét a víznyomás alatt.', 'arviz_belviz'),
    ('Miért veszélyes az árvíz levonulása után azonnal visszatérni a megrongálódott épületbe hatósági engedély nélkül?', '["Csak azért kellemetlen, mert a nedves burkolatok felszáradása több napot is igénybe vehet.", "Az átázott falak statikailag meggyengülhettek, és fertőző szennyvíz maradhatott.", "Mert a levonuló ár után az épületekben átmenetileg gyengébb lehet a mobiltelefon-térerő."]'::jsonb, 1, 'A víz alámoshatja az alapozást és a közművezetékeket; a visszaköltözést statikai és közegészségügyi ellenőrzésnek kell megelőznie.', 'arviz_belviz'),
    ('Mit tegyél az ivóvízzel és az élelmiszerekkel elöntéssel érintett területen?', '["Nyugodtan fogyasztható a vezetékes csapvíz és az ásott kút vize mindenféle forralás nélkül.", "Csak palackozott vagy hatóságilag bevizsgált ivóvizet fogyassz, és dobd ki az árvízzel érintkezett élelmiszert", "Az árvízzel érintkezett kerti zöldségeket és felbontott élelmiszereket elég hideg vízzel leöblíteni."]'::jsonb, 1, 'Az árvíz emésztőgödröket és vegyszertárolókat is elönthet, így a vezetékes és kútvíz is súlyosan szennyeződhet.', 'arviz_belviz'),
    ('Hogyan védekezhetsz otthonodban a csatornarendszeren keresztül visszatorlódó szennyvíz ellen árvíz idején?', '["Semmit nem lehet tenni", "Visszacsapó szeleppel, illetve az összefolyók lezárásával és lesúlyozásával.", "Sajnos semmilyen műszaki vagy ideiglenes védekezési módszer nem létezik visszatorlódás ellen."]'::jsonb, 1, 'A megemelkedett vízszint a csatornahálózaton át a pincékben és földszinti helyiségekben törhet fel, ha nincs visszacsapó szelep.', 'arviz_belviz'),
    ('Mit vigyél magaddal mindenképp, ha a hatóságok elrendelik a lakóhelyed kitelepítését (evakuálását)?', '["Elsősorban a nagyméretű televíziót, a mikrohullámú sütőt és a kerti szerszámkészletet.", "Okmányokat, szedett gyógyszereket, vizet, meleg ruhát és töltött telefont.", "Semmit nem szabad összekészíteni, elegendő egy szál nyári ruhában, iratok nélkül elindulni."]'::jsonb, 1, 'A kész előre összekészített vészhelyzeti csomag (túlélőcsomag) percekkel rövidíti le az elindulást, és biztosítja az ellátást a befogadóhelyen.', 'arviz_belviz'),
    ('Mi a belvíz fő jellemzője és kialakulásának oka?', '["Hirtelen lezúduló hegyvidéki sárlavina, amely sziklákat és kidőlt fákat sodor a völgybe.", "Síkvidéki területeken a telített talaj, az olvadó hó és a csapadék miatt a felszínen összegyűlő, elszivárogni nem tudó víz", "A folyók felső szakaszán kialakuló jégtorlasz, amely percek alatt átszakítja a magaspartot."]'::jsonb, 1, 'A belvíz lassabban alakul ki, mint a villámárvíz, de hetekig tartó elöntéssel áztatja alá az épületeket és teszi tönkre a termést.', 'arviz_belviz'),
    ('Szabad-e belterületen (kertben) avart és kerti zöldhulladékot égetni Magyarországon?', '["Igen, bármikor korlátozás nélkül", "Alapesetben tilos; csak ott szabad, ahol önkormányzati rendelet engedélyezi.", "Minden hétvégén és munkaszüneti napon sötétedés után külön engedély nélkül is megengedett."]'::jsonb, 1, 'Az országos szabályozás tiltja a belterületi avarégetést; kizárólag ott és akkor szabad, ahol ezt helyi önkormányzati rendelet szabályozza.', 'szabadteri_tuz'),
    ('Mit jelent az Országos Tűzgyújtási Tilalom elrendelése?', '["Kizárólag a belvárosi társasházak erkélyén történő elektromos grillezést tiltja meg.", "Erdőkben és 200 méteres körzetükben még a kijelölt tűzrakóhelyen is tilos tüzet gyújtani.", "A kijelölt erdei szalonnasütő helyeken ilyenkor is korlátozás nélkül szabad tüzet rakni."]'::jsonb, 1, 'Fokozott tűzveszély idején a kijelölt erdei tűzrakóhelyek használata is szigorúan tilos a száraz aljnövényzet miatt.', 'szabadteri_tuz'),
    ('Mekkora bírsággal sújtható, aki megszegi a tűzgyújtási tilalmat vagy gondatlanságból szabadtéri tüzet okoz?', '["Csak szóbeli figyelmeztetés jár érte", "Akár 100 000 és 3 000 000 Ft közötti tűzvédelmi bírsággal, plusz a tűzoltás költségeivel", "Egységesen legfeljebb 5 000 forintos helyszíni bírsággal, egyéb költségtérítés nélkül."]'::jsonb, 1, 'A szabadtéri tüzek hatalmas természeti és anyagi kárt okoznak, ezért a hatóság magas bírságot szab ki, és behajtja a vonulási költségeket is.', 'szabadteri_tuz'),
    ('Mire kell figyelni, ha a saját kertedben grillezel vagy bográcsozol?', '["Elég, ha a tűz meggyújtása után bemész a házba", "Ne hagyd őrizetlenül a tüzet, és legyen kéznél oltóanyag (víz, slag, homok).", "Erős, viharos szélben érdemes begyújtani a faszenet, mert a huzat gyorsabban izzítja át."]'::jsonb, 1, 'Egyetlen hirtelen széllökés is parazsat fújhat a száraz fűbe vagy a szomszédos tujasorba – az azonnali oltóanyag életmentő.', 'szabadteri_tuz'),
    ('Hogyan kell helyesen eloltani a szabadtéri tüzet a program végén?', '["Szórj a még izzó parázsra száraz faleveleket és gallyakat, majd hagyd ott a tűzrakóhelyet.", "Bő vízzel vagy földdel teljesen le kell hűteni a parazsat, amíg nem füstöl.", "Hagyd szabadon parázslani éjszakára, mert a hajnali harmat minden esetben magától eloltja."]'::jsonb, 1, 'A hamu alatt megbújó parázs órákkal később, a szél feltámadásával újra lángra lobbanhat.', 'szabadteri_tuz'),
    ('Miért különösen veszélyes a tavaszi száraz fű és nádas felgyújtása (tarlóégetés)?', '["Csak esztétikai problémát okoz, mert a fekete pernye összekoszolja a kerti bútorokat.", "A száraz növényzetben a tűz futótűzként, akár 30–40 km/h sebességgel terjed, és pillanatok alatt elérheti a lakóházakat és erdőket", "Hasznos eljárás, mert elpusztítja a kártevőket és semmilyen veszélyt nem jelent a környezetre."]'::jsonb, 1, 'A tarló- és nádaségetés tilos és életveszélyes: a szélirány megváltozása a tűzgyújtót is körbezárhatja.', 'szabadteri_tuz'),
    ('Miért okozhat erdőtüzet egy eldobott üvegpalack vagy üvegszilánk a természetben?', '["Mert megvágja az állatokat", "A napsugarakat gyújtólencseként összegyűjtve meggyújtja a száraz avart.", "Mert az esővízzel érintkező üvegszilánk hőtermelő kémiai reakcióba lép a termőtalajjal."]'::jsonb, 1, 'Az üvegben megtörő napfény könnyedén eléri a száraz levelek és fűszálak gyulladási hőmérsékletét.', 'szabadteri_tuz'),
    ('Hogyan szabad megszabadulni a cigarettacsikktől autóban vagy kirándulás közben?', '["Kidobhatod az autó ablakán menet közben, mert a menetszél azonnal eloltja a parazsat.", "Csak teljesen elnyomva, zárt hamutartóban; a természetben soha ne dobd el.", "Erdőszélen elegendő száraz fűcsomóba ejteni és egyetlen gyors mozdulattal rálépni."]'::jsonb, 1, 'Az út menti száraz gaz és az erdei avar az eldobott, még parázsló csikkektől gyullad meg leggyakrabban.', 'szabadteri_tuz'),
    ('Mit tegyél azonnal, ha szabadtéri tüzet (füstöt vagy lángokat) észlelsz a határban vagy az erdőben?', '["Szaladj a lángok elé szélirányba, hogy közelről készíthess felvételt a közösségi oldalakra.", "Távolodj el biztonságos irányba (széliránnyal szemben vagy oldalirányba), és azonnal hívd a 112-t a pontos helyszín megadásával", "Próbáld meg egyedül, kabáttal csapkodva megállítani a gyorsan terjedő magas lángfalat."]'::jsonb, 1, 'A gyors jelzés kulcsfontosságú, hogy a tűzoltók még a tűz továbbterjedése előtt beavatkozhassanak.', 'szabadteri_tuz'),
    ('Hogyan teheted tűzbiztosabbá a házad környékét tavasszal és nyáron?', '["Tárolj száraz tűzifát közvetlenül a terasz alatt.", "Nyírd a füvet, és távolítsd el a száraz ágakat, avart a ház körül és az ereszből.", "Hagyd megnőni a derékig érő száraz gazt a kerítés mentén, mert az felfogja a szálló pernyét."]'::jsonb, 1, 'Az épület körüli védőzóna megakadályozza, hogy egy esetleges szomszédos vegetációtűz átterjedjen a tetőszerkezetre.', 'szabadteri_tuz')
)
UPDATE public.quiz_questions AS q
SET options = b.options,
    correct_index = b.correct_index,
    explanation = b.explanation,
    category = b.category
FROM balanced AS b
WHERE q.question = b.question;

INSERT INTO public.quiz_questions (question, options, correct_index, explanation, category)
SELECT b.question, b.options, b.correct_index, b.explanation, b.category
FROM (
  VALUES
    ('Füstöt észlelsz a lakás folyosóján. Mi a legfontosabb?', '["Biztonságos útvonalon menekülni és a 112-t hívni.", "Előbb összeszedni az értéktárgyakat.", "Kinyitni minden ajtót, hogy kiszellőzzön."]'::jsonb, 0, 'Csak biztonságosan járható útvonalon menekülj. Sűrű füsttel telt lépcsőházba ne lépj be. Ha a kijutás veszélyes, csukd be az ajtót, hívd a 112-t, és jelezd, hol vagy; kövesd a tűzoltók utasításait.', 'altalanos'),
    ('Miért kell füstben lehetőleg alacsonyan haladni?', '["Mert a padlón mindig friss levegő van.", "A hő és a füst jellemzően felfelé száll.", "Mert négykézláb haladva sokkal kisebb az elbotlás és a sérülés veszélye."]'::jsonb, 1, 'Alacsonyabban általában kedvezőbbek a körülmények, de a füst ott is mérgező lehet.', 'altalanos'),
    ('Mit teszel, ha egy edényben ég a főzőolaj?', '["Azonnal hideg csapvizet öntesz rá, hogy lehűtsd a lángoló zsiradékot.", "Óvatosan megfogod konyharuhával, és kiviszed az égő edényt az erkélyre.", "Elzárod a hőt és fedővel letakarod; vizet tilos ráönteni."]'::jsonb, 2, 'Az égő olajra öntött víz súlyos lángfellobbanást okozhat. Veszély esetén távolodj el és hívd a 112-t.', 'altalanos'),
    ('Mit ellenőrzöl menekülés előtt egy zárt ajtónál?', '["Óvatosan ellenőrzöd, nem forró-e az ajtó; forró ajtót nem nyitsz ki.", "Azonnal feltéped, hogy gyorsabban kijuss.", "Vizet öntesz a kilincsre és belépsz."]'::jsonb, 0, 'A forró ajtót ne nyisd ki. A nem forró ajtó sem garantál füstmentes útvonalat. Ha nincs biztonságos kijárat, csukott ajtó mögül hívd a 112-t és jelezd a tartózkodási helyedet.', 'altalanos'),
    ('Mire jó az otthoni füstérzékelő?', '["Automatikusan elolt minden tüzet.", "Korán jelzi a füstöt, így időt ad a menekülésre.", "Teljesen kiváltja az otthoni menekülési tervet és a tűzoltó készüléket."]'::jsonb, 1, 'A korai figyelmeztetés életmentő lehet; az érzékelőt rendszeresen ellenőrizni kell.', 'altalanos'),
    ('Mit teszel, ha egy lítiumakkumulátoros eszköz füstöl és sziszeg?', '["Vastag kesztyűvel megfogod, és gyorsan bedobod a konyhai mosogatómedencébe.", "Közelről megvizsgálod a készüléket, és azonnal kihúzod belőle az akkumulátort.", "Eltávolodsz a füsttől, másokat is kiküldesz, és 112-t hívsz."]'::jsonb, 2, 'A sérült akkumulátor mérgező gázokat bocsáthat ki, és újra meggyulladhat.', 'altalanos'),
    ('Mit teszel, ha menekülés közben biztonságosan magad mögött becsukhatod az ajtót?', '["Becsukod, ezzel lassíthatod a tűz és a füst terjedését.", "Mindig nyitva hagyod a huzat miatt.", "Kiékeled teljesen nyitott helyzetben."]'::jsonb, 0, 'A zárt ajtó lassíthatja a tűz és a füst továbbterjedését.', 'altalanos'),
    ('Miért fontos a családi menekülési terv?', '["Csak a biztosító miatt.", "Mindenki előre tudja, merre juthat ki és hol találkoztok.", "Hogy vészhelyzetben pontosan beosszátok, ki melyik műszaki cikket menti ki."]'::jsonb, 1, 'A kijáratok és menekülési útvonalak előzetes ismerete csökkenti a bizonytalanságot.', 'altalanos'),
    ('Mit jelent az elzárkózás veszélyesanyag-felhő esetén?', '["Azonnal gépkocsiba ülni, és megpróbálni kikerülni a terjedő gázfelhőt.", "Minden nyílászárót kitárni, hogy a lakásban ne halmozódjon fel a gáz.", "Épületben maradni, bezárni az ablakokat és figyelni a híreket."]'::jsonb, 2, 'Veszélyesanyag-felhőnél a külső levegő bejutását kell csökkenteni a hatósági tájékoztatásnak megfelelően.', 'altalanos'),
    ('Mit kell tenni elzárkózáskor a külső levegőt beszívó klímával?', '["Kikapcsolni a külső levegőt bejuttató szellőztetést.", "Maximális fokozatra kapcsolni.", "Ablakot nyitni mellé."]'::jsonb, 0, 'A külső levegő bejuttatása szennyező anyagokat hozhat az épületbe.', 'altalanos'),
    ('Mi a különbség kitelepítés és kimenekítés között?', '["Nincs különbség, mindkettő ugyanaz.", "A kitelepítés előre tervezhető, a kimenekítés azonnali veszély miatti.", "A kitelepítés kizárólag önkéntes döntés, a kimenekítés pedig csak gyakorlat."]'::jsonb, 1, 'A polgári védelem külön kezeli az előre tervezhető és a sürgős lakóhelyelhagyást.', 'altalanos'),
    ('Melyik a legfontosabb összeállítás egy hosszabb kitelepítésre?', '["Nagy értékű szórakoztatóelektronikai eszközök, laptop és családi fotóalbumok.", "Többheti fagyasztott élelmiszerkészlet és nehéz konyhai kisgépek dobozban.", "Okmányok, gyógyszerek, víz, tartós étel, ruha és higiéniai cikkek."]'::jsonb, 2, 'A csomag legyen személyre szabott, könnyen hordozható, és igazodjon a hatóság tájékoztatásához.', 'altalanos'),
    ('Miért praktikus hátizsákban vinni a veszélyhelyzeti csomagot?', '["Szabadon maradnak a kezeid mozgáshoz és segítségnyújtáshoz.", "Mert minden hátizsák vízhatlan.", "Mert így több száz kilót vihetsz."]'::jsonb, 0, 'A könnyen hordozható csomag különösen fontos gyalogos mozgásnál.', 'altalanos'),
    ('Mit tegyél, ha hivatalosan elrendelik a kitelepítést?', '["Várj napokat további magyarázat nélkül.", "Kövesd a kijelölt útvonalat és a hatóságok utasításait.", "Indulj el önállóan földutakon, hogy elkerüld a főutakon kialakuló torlódást."]'::jsonb, 1, 'A szervezett mozgás és a tájékoztatás követése fontos az életvédelemhez.', 'altalanos'),
    ('Mire kell gondolni különösen a veszélyhelyzeti csomag tervezésekor?', '["Kizárólag a családfenntartó felnőttek eredeti okmányaira és bankkártyáira.", "Arra, hogy minden családtag pontosan egyforma felszerelést és ruhát kapjon.", "Gyermekek, idősek és tartós betegek egyéni szükségleteire."]'::jsonb, 2, 'A személyes szükségletek, gyógyszerek és segédeszközök nélkülözhetetlenek lehetnek.', 'altalanos'),
    ('Mikor szellőztess egy veszélyesanyag-felhő miatti elzárkózás után?', '["Ha a hatósági tájékoztatás szerint elmúlt a veszély.", "Az első szirénaszó alatt.", "Amikor a felhő a ház elé ér."]'::jsonb, 0, 'A szellőztetés idejét a helyi utasítások és a veszély elmúlása határozza meg.', 'altalanos'),
    ('Hosszabb áramszünet alatt mit tegyél a hűtőszekrény ajtajával?', '["Percenként nyitogasd.", "Lehetőleg tartsd végig csukva az ajtaját.", "Támaszd ki résnyire, hogy ne keletkezzen kellemetlen szag a hűtőtérben."]'::jsonb, 1, 'A hűtő ajtajának csukva tartása lassítja a felmelegedést. Egy előzőleg megfelelően hűtött, zárva tartott hűtő nagyjából 4 órán át tarthatja biztonságosan hidegen az ételt. Hosszabb kimaradásnál a hőmérséklet és az élelmiszer típusa alapján kell dönteni; kóstolással ne ellenőrizd a biztonságot.', 'altalanos'),
    ('Hol szabad működtetni egy benzinmotoros áramfejlesztőt?', '["Jól szellőző pincében vagy garázsban, ha a garázskaput félig nyitva hagyod.", "Fedett előtérben vagy zárt verandán, közvetlenül a nyitott ablak alá téve.", "Csak szabadban, az épülettől és nyílászáróktól legalább 6 méterre."]'::jsonb, 2, 'Az áramfejlesztő kipufogógáza életveszélyes szén-monoxidot tartalmaz. Garázsban vagy más zárt térben nyitott ajtó mellett sem működtethető. A gyártó ennél nagyobb távolságot is előírhat.', 'altalanos'),
    ('Mivel NEM szabad fűteni áramszünetkor?', '["Beltérben használt kerti grillsütővel vagy gáztűzhellyel.", "Biztonságosan alkalmazott, erre tervezett fűtőberendezéssel.", "Megfelelő meleg ruházattal és takaróval."]'::jsonb, 0, 'Az égéstermékek és a szén-monoxid mérgezést okozhatnak.', 'altalanos'),
    ('Erős gázszagot észlelsz a lakásban. Mi a biztonságos reakció?', '["Kapcsold fel sorban a villanyokat.", "Ne kapcsolj villanyt; zárd el a gázt, menj ki és kintről hívj segítséget.", "Indítsd el a konyhai páraelszívót maximális fokozaton az ablak kinyitása mellett."]'::jsonb, 1, 'Ne működtess kapcsolót, ne húzz ki dugót, és ne telefonálj a gázszagú térben. A gázt csak saját veszélyeztetésed nélkül zárd el. Hagyd el a helyet, és biztonságos távolságból hívd a gázszolgáltatót vagy közvetlen veszélyben a 112-t.', 'altalanos'),
    ('Miért kell áramszünetkor a fontos egészségügyi eszközökre is tervezni?', '["Mert minden otthoni gyógyászati berendezés legalább egy hétig bírja akkumulátorról.", "Mert áramszünet idején az elektromos orvosi készülékek maguktól újraindulnak.", "Egyes orvosi eszközök és gyógyszerek áramot vagy hűtést igényelnek."]'::jsonb, 2, 'Életfontosságú eszköz esetén előre kidolgozott tartalék áramellátási és ellátási terv szükséges.', 'altalanos'),
    ('Miért érdemes a nem életfenntartó, érzékeny elektronikus készülékeket kihúzni áramszünetben?', '["A visszatérő áramellátáskor fellépő túlfeszültség elleni védelem miatt.", "Hogy gyorsabban jöjjön vissza az áram.", "Mert a dugó mindig felrobban áram nélkül."]'::jsonb, 0, 'A hálózat visszakapcsolásakor fellépő túlfeszültség károsíthatja az érzékeny berendezéseket. Orvosi, életfenntartó eszközöknél az előre egyeztetett ellátási tervet kövesd.', 'altalanos'),
    ('A szén-monoxid-érzékelő CO-veszélyjelzést ad. Mit teszel?', '["Biztosan csak lemerült a telefon.", "Azonnal hagyd el az épületet, és kintről kérj segítséget.", "Kapcsold be a fürdőszobai elszívóventilátort, és feküdj le pihenni a szobában."]'::jsonb, 1, 'A CO színtelen, szagtalan és életveszélyes. Menj biztonságos helyre, kérj segítséget, és ne térj vissza a veszélyes térbe hibát keresni. Az elem- vagy készülékhiba-jelzéseket a gyártói útmutató különíti el a CO-riasztástól.', 'altalanos'),
    ('Mit érdemes kéznél tartani váratlan áramszünetre?', '["Több szál égő viaszgyertyát minden szobában, éjszakára is égve hagyva.", "Kizárólag vezetékes asztali telefont és hálózati 230 voltos halogén reflektorokat.", "Feltöltött telefont, powerbankot, elemlámpát és elemes rádiót."]'::jsonb, 2, 'Az önálló energiaforrás és a hiteles tájékoztatás elérése alapvető.', 'altalanos'),
    ('Nagy hóban elakadsz egy elhagyatott úton. Mi az elsődleges?', '["Segítséget kérsz és megadod a helyzeted; ha a járműnél nem fenyeget közvetlen veszély, ott maradsz védett helyen.", "Indulj el azonnal gyalogosan a szántóföldön át a legközelebbi település irányába.", "Kapcsold le az összes világítást, és zárd el teljesen a levegő utánpótlását."]'::jsonb, 0, 'Erős hóviharban a jármű védelmet adhat és könnyebben megtalálható; közvetlen veszély esetén más döntés szükséges.', 'altalanos'),
    ('Miért kell a kipufogót szabaddá tenni, mielőtt a havas úton járatod a motort?', '["Hogy hangosabban szóljon a motor.", "Az utastérbe jutó szén-monoxid-mérgezés elkerüléséért.", "Hogy a forró kipufogógáz ne olvassza meg a hátsó lökhárító műanyag elemeit."]'::jsonb, 1, 'A hó eltömítheti a kipufogót, és a kipufogógáz visszajuthat a járműbe.', 'altalanos'),
    ('Melyik felszereléscsomag a leghasznosabb hosszú téli útra?', '["Csak egy műanyag jégkaparó, páramentesítő kendő és nyári szélvédőmosó folyadék.", "Pótkerék helyett defektjavító spray, napszemüveg és vékony esőkabát a csomagtérben.", "Takaró, meleg ruha, víz, étel, lámpa, hólapát és töltött telefon."]'::jsonb, 2, 'A magyar rendőrség is hangsúlyozza az úti és téli vészfelszerelés fontosságát.', 'altalanos'),
    ('Melyikre érdemes figyelni téli indulás előtt?', '["Időjárás, útviszonyok, abroncsok, akkumulátor és világítás.", "Csak az autórádió hangerőre.", "Csak az üléskárpitra."]'::jsonb, 0, 'A technikai állapot és a tájékozódás csökkentheti az elakadási és baleseti kockázatot.', 'altalanos'),
    ('Hóviharban elakadt autót látsz. Mit tegyél?', '["Azonnal megállsz az úttest közepén.", "Biztonságos helyről mérd fel a helyzetet, szükség esetén hívd a 112-t.", "Hajts tovább megállás és bejelentés nélkül, mert télen ez mindennapos jelenség."]'::jsonb, 1, 'Saját biztonságod elsődleges; a bajba jutók helyét és állapotát pontosan jelezd a segélyhívón.', 'altalanos'),
    ('Meghibásodás miatt biztonságosan megálltál az út szélén. Mi segítheti a láthatóságot?', '["A teljes világítás lekapcsolása, hogy ne merüljön le idő előtt az akkumulátor.", "A csomagtérajtó felnyitása vészvillogó és elakadásjelző háromszög használata nélkül.", "Vészvillogó, láthatósági mellény és elakadásjelző háromszög."]'::jsonb, 2, 'A vészvillogó és a körülményeknek megfelelő elakadásjelzés figyelmeztethet másokat. A jelzés kihelyezése ne sodorjon új veszélybe. Autópályán a járműben várakozás helyett a szalagkorláton kívüli védett hely lehet szükséges; kövesd a helyszíni útmutatást.', 'altalanos'),
    ('Elakadás közben hogyan csökkentheted a kihűlés kockázatát?', '["Száraz, réteges ruházattal, takaróval és szükség esetén szakszerű segítségkéréssel.", "Tömény szeszes ital fogyasztásával, mert az tartósan megemeli a belső testhőt.", "Folyamatos ki-be szállással és a hóban végzett intenzív futással az autó körül."]'::jsonb, 0, 'A kihűlés megelőzéséhez a száraz ruházat és a hőveszteség csökkentése fontos.', 'altalanos'),
    ('Hóviharban, biztonságos helyen várakozva mi igaz a fűtés céljából járatott motorra?', '["Órákon át folyamatosan járhat, zárt ablakok mellett.", "Csak szakaszosan járjon, szabad kipufogó és résnyire nyitott ablak mellett.", "Csak belső levegőkeringtetéssel szabad járatni, a kipufogót nem kell ellenőrizni."]'::jsonb, 1, 'A hóviharban várakozó járműnél az NWS rövid, szakaszos motorjáratást javasol, például óránként körülbelül 10 percet. A kipufogó legyen szabad, és biztosítani kell a szellőzést. Ez nem általános biztonsági garancia: CO-kockázat vagy más közvetlen veszély esetén kérj sürgős segítséget.', 'altalanos'),
    ('Mit kell tenni, ha lakott területen hirtelen, rendkívül erős szélvihar (orkán) tör ki az utcán?', '["Állj be egy terebélyes fa vagy magas reklámtábla alá, amíg elvonul a széllökés.", "Kerüld a fákat és vezetékeket, menj mielőbb stabil épületbe.", "Kapaszkodj meg egy utcai villanyoszlopban vagy ideiglenes építési állványzatban."]'::jsonb, 1, 'Kerüld a leszakadó ágakat és tárgyakat. Ne állj meg sérült épületrész alatt; keress biztonságos menedéket.', 'altalanos'),
    ('Mit jelent a HungaroMet piros figyelmeztetése magas középhőmérséklet miatt?', '["Csak mérsékelt nyári felmelegedést jelez, elegendő szalmakalapot viselni délben.", "Kiemelten veszélyes hőséget jelez; csökkenteni kell a megterhelést, hűvös helyet keresni és követni a hivatalos tájékoztatást.", "Kizárólag a mezőgazdasági öntözőrendszerek üzemeltetőinek szóló technikai jelzés."]'::jsonb, 1, 'A meteorológiai figyelmeztetés és az egészségügyi hőségriasztás külön rendszer. Nem azonos a szociális ellátás vörös kódjával.', 'altalanos'),
    ('Hogyan kell védekezni villámárvizek (hirtelen lezúduló nagy esők miatti áradások) esetén?', '["Le kell menni a mélygarázsba megnézni az autót.", "Menj magasabb terepre, és kerüld az aluljárókat, pincéket.", "Állj be gépkocsival a legmélyebb közúti aluljáróba, amíg a felhőszakadás eláll."]'::jsonb, 1, 'Minél gyorsabban el kell jutni a magasabban fekvő, biztonságos területekre, és kerülni kell az aluljárókat, pincéket.', 'altalanos'),
    ('Mi a teendő, ha autózás közben hatalmas jégeső lep meg?', '["Gyorsíts fel, hogy minél rövidebb ideig tartózkodj a jégveréssel érintett zónában.", "Lassíts, és állj meg biztonságos helyen, fáktól távol.", "Állj meg hirtelen a belső sávban vagy közvetlenül egy út menti fasor árnyékában."]'::jsonb, 1, 'Ne állj meg forgalmi sávban vagy híd alatt úgy, hogy másokat veszélyeztetsz. Maradj a járműben, amíg biztonságosan tovább lehet indulni.', 'altalanos'),
    ('Mit jelent a másodfokú (narancs) riasztás zivatar és felhőszakadás esetén?', '["Csendes, veszélytelen nyári záport jelent, amely nem igényel semmilyen óvintézkedést.", "Fokozott veszélyt jelez; figyelni kell a friss előrejelzéseket és felkészülni a heves időjárás hatásaira.", "Kötelező érvényű országos kijárási és közlekedési tilalom automatikus életbelépését."]'::jsonb, 1, 'A narancssárga jelzés veszélyes időjárást jelez, de önmagában nem jelent kijárási tilalmat.', 'altalanos'),
    ('Hová menj, ha túrázás közben meghallod a mennydörgést?', '["Magas fa teteje vagy egy magányos fa töve.", "Menj stabil épületbe vagy zárt, keménytetős gépkocsiba.", "Maradj a hegytetőn felállított túrasátorban a fém sátorrudak mellé kuporodva."]'::jsonb, 1, 'Szabadban nincs villámbiztos hely. A guggolás nem teszi biztonságossá a helyzetet.', 'altalanos'),
    ('Mi az elsődleges veszélyforrás egy tartós, heves téli hófúvás (blizzard) során?', '["A hirtelen megemelkedő légnedvesség miatti nyári hőpangás és napszúrás.", "A kihűlés, az utakon való elakadás és az áramkimaradás.", "A talajvíz azonnali felforrósodása és a felszíni UV-sugárzás megugrása."]'::jsonb, 1, 'A kihűlés (hipotermia), a magányos utakon elakadás és a fűtés/áramkimaradás.', 'altalanos'),
    ('Mit kell tenni, ha lakóhelyeden hirtelen bekövetkező, extrém vihar miatt elmegy az áram és a fűtés?', '["Szellőztess ki egyszerre minden szobát, hogy kiegyenlítsd a külső-belső hőmérsékletet.", "Meleg ruhát ölteni, lezárni a kihűlő helyiségeket, és bekapcsolni az elemes rádiót a friss információkért.", "Kapcsold be a konyhai gázsütőt nyitott ajtóval, hogy befűtse az egész lakást."]'::jsonb, 1, 'Öltözz melegen, tartsd meg a hőt és figyeld a hivatalos híreket. Beltérben ne használj kültéri égésű eszközt vagy áramfejlesztőt.', 'altalanos'),
    ('Mit jelez a meteorológiában a ''szupercella'' kifejezés?', '["Egy óriási felhőkarcolót Budapesten.", "Forgó feláramlású heves zivatar; nagy jégesőt és orkánt okozhat.", "A meteorológiai radarállomások legújabb generációs napelemes mérőegysége."]'::jsonb, 1, 'Nem minden szupercella okoz tornádót. A veszélyjelzéseket kell követni, nem egy felhő látványából dönteni.', 'altalanos'),
    ('Mi a teendő erdőtűz esetén, ha észreveszed a lángokat a kirándulás során?', '["Futva indulj el a széllel megegyező irányba a sűrű fenyves belseje felé.", "Távolodj el biztonságos irányba, hívd a 112-t és kövesd az utasítást.", "Menj egészen közel a lángokhoz fotót készíteni, mielőtt bejelentenéd a tüzet."]'::jsonb, 1, 'A szél és a terep gyorsan változtathatja a tűz terjedését; egyetlen általános irányszabály nem garantál menekülést.', 'altalanos'),
    ('Mely tünetek utalhatnak hőgutára?', '["Enyhe torokkaparás, tüsszögés és normális, 36,5 °C körüli testhőmérséklet.", "Nagyon magas testhőmérséklet, zavartság, rossz koordináció, eszméletvesztés; a bőr lehet száraz vagy verejtékes.", "Fokozott éhségérzet, élénk koncentráció és lassú, nyugodt szívverés pihenéskor."]'::jsonb, 1, 'Hőguta gyanújánál azonnali segélyhívás és hűtés szükséges. Ne várj arra, hogy magától rendeződjön.', 'altalanos'),
    ('Mi a helyes döntés, ha elöntött útszakaszhoz érsz autóval?', '["Maradj benne üvöltve, amíg el nem apad.", "Ne hajts a vízbe; fordulj vissza és keress biztonságos kerülőutat.", "Kövesd szorosan az előtted haladó teherautót a mély vízzel borított útszakaszon."]'::jsonb, 1, 'Ne alapozd a biztonságot a kerék vagy küszöb magasságára. A víz mélysége, sodrása és az út állapota kívülről nem ítélhető meg.', 'altalanos'),
    ('Hogyan védekezzünk az UV-sugárzás ellen nyári napokon szabadtéren?', '["Déli órákban vizes bőrrel napozz árnyék nélkül, mert a víz kiszűri a sugarakat.", "Keress árnyékot, viselj fejfedőt, napszemüveget és használj naptejet.", "Csak borult időben használj szemvédelmet, kánikulában kerüld a folyadékpótlást."]'::jsonb, 1, 'Árnyék, megfelelő ruházat, fejfedő, napszemüveg és megfelelő fényvédő; erős UV idején kerülni kell a tűző napot.', 'altalanos'),
    ('Mi a teendő szén-monoxid mérgezés gyanúja esetén otthon?', '["Zárd be az ablakokat, feküdj le pihenni, és várj, amíg a fejfájás magától elmúlik.", "Azonnal kijutni a friss levegőre, másokat is figyelmeztetni és biztonságos helyről 112-t hívni.", "Gyújts meg egy öngyújtót a kazán mellett, hogy ellenőrizd az oxigénszintet."]'::jsonb, 1, 'Ne késleltesd a kijutást a berendezés keresésével vagy szellőztetéssel, és ne menj vissza a veszélyes térbe.', 'altalanos'),
    ('Mi a lakosság feladata súlyos időjárási veszélyjelzéskor?', '["Bezárja az összes boltot és bankot.", "Figyelni a hivatalos híreket és kerülni a felesleges utazást.", "Kimenni a szabadba megfigyelni és közelről videózni az érkező viharfrontot."]'::jsonb, 1, 'A meteorológiai piros jelzés és a szociális vörös kód nem azonos. Az intézkedések az adott eseménytől függnek.', 'altalanos'),
    ('Mikor kell figyelni a heves zivatarok veszélyére Magyarországon?', '["Kizárólag a téli fagyos hónapokban, december közepe és február vége között.", "Főként a meleg évszakban, de mindig a veszélyjelzés alapján.", "Csak páros évek tavaszán, amikor a folyók vízállása tartósan alacsony marad."]'::jsonb, 1, 'A naptári hónap önmagában nem zárja ki a heves zivatar lehetőségét.', 'altalanos'),
    ('Melyik tünet utalhat kezdődő kihűlésre?', '["Hirtelen kipirult, forró arcbőr, bőséges izzadás és szokatlanul élénk beszéd.", "Remegés, hideg bőr és romló kézügyesség; súlyosbodáskor zavartság és beszédzavar is jelentkezhet.", "Erős szomjúságérzet, szapora pislogás és a testhőmérséklet gyors emelkedése."]'::jsonb, 1, 'A hipotermia kihűlést jelent, nem eleve halált. Súlyos gyanú esetén 112 és kíméletes védelem a további hővesztéstől.', 'altalanos'),
    ('Mi a helyes eljárás, ha fagyos időben beszakad valaki alatt a jég a tavon?', '["Rohanva odafutni a lék szélére.", "Hívd a 112-t, és a partról nyújts biztonságos segítséget.", "Dobálj nehéz köveket a jégre a bajbajutott mellé, hogy nagyobb legyen a nyílás."]'::jsonb, 1, 'A hason csúszás sem garantálja a jég teherbírását. Ne válj második áldozattá.', 'altalanos'),
    ('Mi az a ''száraz villám''?', '["Olyan különleges téli villámlás, amely csak befagyott tavak felett jöhet létre.", "Villámlás, amikor a csapadék nem éri el a felszínt; tüzet okozhat.", "Elektromos kisülés, amely teljesen hangtalan és soha nem jelent tűzveszélyt."]'::jsonb, 1, 'Az eső hiánya nem zárja ki a villámcsapást. Az erdőtüzek okai területenként eltérnek; nem állítjuk, hogy mindenütt ez a fő ok.', 'altalanos'),
    ('Mit kell tenni erős földrengés alatt zárt térben?', '["Azonnal szaladj ki az erkélyre vagy hívd a liftet, hogy lejuss a földszintre.", "Leguggolni, fedezékbe húzódni és kapaszkodni; védeni a fejet, kerülni az ablakokat és a liftet.", "Állj közvetlenül a legnagyobb üvegablak vagy egy magas könyvespolc elé."]'::jsonb, 1, 'Stabil asztal alatt védd a fejed, és kapaszkodj. Ne rohanj a rázkódás közben a kijárathoz.', 'altalanos'),
    ('Mit tartalmazzon egy jól összeállított 72 órás vészhelyzeti hátizsák (Bug-out bag)?', '["Csak divatos ruhákat és egy tabletet.", "Vizet, tartós ételt, elsősegélyt, lámpát, rádiót és gyógyszert.", "Friss tejet, fagyasztott húst és hálózati hosszabbítót elemek és ivóvíz nélkül."]'::jsonb, 1, 'Ivóvizet, tartós élelmiszert, elsősegélycsomagot, zseblámpát, elemes rádiót, iratmásolatot és gyógyszereket.', 'altalanos'),
    ('Hogyan kell vízhez jutni a vadonban, ha kifogytál az ivóvízből?', '["Igyál bátran bármilyen erdei pocsolyából, ha a víz szabad szemmel átlátszónak tűnik.", "Keress biztonságos forrást; a természetes vizet mindig kezeld.", "Fogyassz sós vizet vagy olvasztott útszéli havat szűrés és forralás nélkül."]'::jsonb, 1, 'A forralás a kórokozók ellen segíthet, de a vegyi szennyeződést nem távolítja el. Nem minden szűrő távolít el minden kórokozót.', 'altalanos'),
    ('Mit tegyél jelentős külső vérzés esetén, ha a helyszín biztonságos?', '["Hagyd szabadon vérezni a sebet, hogy a szennyeződés magától kimosódjon belőle.", "Erős, közvetlen nyomást gyakorolni a sebre tiszta kötszerrel, segítséget hívni és követni a 112 utasításait.", "Húzd ki azonnal a sebbe ékelődött idegentestet, majd szórj hintőport a nyílásba."]'::jsonb, 1, 'Az elsődleges cél a vérveszteség csökkentése. Beékelődött tárgyat nem húzunk ki; körülötte alkalmazunk nyomást.', 'altalanos'),
    ('Hogyan jelölheted meg a tartózkodási helyedet, ha segítséget vársz a mentőktől az erdőben?', '["Elégetni az összes fát.", "Jelezz síppal, lámpával vagy élénk ruhával, és hívd a 112-t.", "Bújj el mozdulatlanul egy sűrű bokor alatt sötét ruhában, és kapcsold ki a telefont."]'::jsonb, 1, 'Jelzés céljából se gyújts tüzet, ha az veszélyes vagy tiltott; a fény és hang biztonságosabb jelzőeszköz lehet.', 'altalanos'),
    ('Mi a helyes öltözködési elv túrázáskor vagy hűvös időben (a hagyma-elv)?', '["Egyetlen vastag pamutpóló és rávett nehéz télikabát köztes szigetelőréteg nélkül.", "Réteges öltözék: izzadságelvezető alap, hőtartó közép és szélálló héj.", "Szoros, nem szellőző műanyag esőruha közvetlenül a meztelen bőrre felvéve."]'::jsonb, 1, 'Réteges öltözködés: nedvességelvezető alsó réteg, hőtartó középső réteg és szél-/vízálló külső héj.', 'altalanos'),
    ('Melyik eszköz a leghasznosabb tájékozódáshoz, ha lemerült a telefonod GPS-e?', '["Egy kockás füzet.", "Analóg tájoló (kompassz) és papíralapú térkép.", "Egy darab faág."]'::jsonb, 1, 'Analóg tájoló (kompassz) és papíralapú térkép.', 'altalanos'),
    ('Hány lakástűz köthető évente Magyarországon az adventi koszorúkhoz a katasztrófavédelem adatai szerint?', '["Kevesebb mint 5", "Átlagosan évi 50–70 lakástűz.", "Több mint 600 súlyos lakástűz indul ki koszorúkból minden decemberben."]'::jsonb, 1, 'Évente átlagosan 50–70 lakástűz indul ki adventi koszorúról, jellemzően felügyelet nélkül hagyott gyertya vagy hiányzó alátét miatt.', 'advent'),
    ('Mire kell mindenképpen figyelni az adventi koszorú elhelyezésekor?', '["Közvetlenül a csipkefüggöny mellé, száraz fenyőágakkal körberakva tegyük le.", "Tűzálló alátétre helyezzük, és legyen alatta fém gyertyatüske.", "Vékony dekorációs műanyag tálcára vagy fonott vesszőkosárba állítsuk tüske nélkül."]'::jsonb, 1, 'A leégő kanóc átégetheti a száraz koszorúalapot; a fém gyertyatartó tüske és a nem éghető alátét megakadályozza a tűz továbbterjedését.', 'advent'),
    ('Mi a legfontosabb szabály, ha elhagyod azt a helyiséget, ahol ég az adventi gyertya?', '["Csak akkor kell elfújni, ha 1 óránál tovább vagy távol", "Mindig fújd el a gyertyát, még akkor is, ha csak néhány percre hagyod el a szobát.", "Elég, ha becsukod a szobaajtót"]'::jsonb, 1, 'Egy kiszáradt koszorú másodpercek alatt lángra kaphat, ezért nyílt lángot soha nem szabad őrizetlenül hagyni.', 'advent'),
    ('Milyen távolságra kell elhelyezni az égő gyertyát a függönytől, terítőtől vagy más éghető anyagtól?', '["Legalább 10 cm-re", "Legalább 50–100 cm távolságra minden éghető anyagtól.", "Nincs szükség semmilyen védőtávolságra, ha egy pohár vizet teszel az asztalra."]'::jsonb, 1, 'A huzat vagy a levegő áramlása könnyen a lángba sodorhatja a függönyt, a papírszalvétát vagy a száraz gallyakat.', 'advent'),
    ('Mit tegyél, ha a kiszáradt adventi koszorú vagy a terítő meggyullad?', '["Próbáld meg puszta kézzel felkapni, és kiszaladni az égő koszorúval a lépcsőházba.", "Takard le vastag nedves textíliával, vagy használj tűzoltó készüléket.", "Tárd ki azonnal az összes ablakot, hogy az erős huzat kifújja a szobából a füstöt."]'::jsonb, 1, 'A letakarás elzárja az oxigént a tűztől, míg az ablaknyitás huzatot kelt és táplálja a lángokat.', 'advent'),
    ('Mire figyelj a karácsonyi fényfüzérek vásárlásakor és használatakor?', '["Bármilyen jelöletlen beltéri égősort nyugodtan felszerelhetsz a havas kerti fákra is.", "Csak magyar nyelvű használati utasítással és CE jelöléssel ellátott terméket vegyél, és éjszakára húzd ki", "A megsérült szigetelésű vezetékeket elegendő átlátszó irodai ragasztószalaggal betekerni."]'::jsonb, 1, 'A hibás, túlmelegedő égősorok zárlatot okoznak; beltéri fényfüzért pedig szigorúan tilos kültéren használni.', 'advent'),
    ('Mi a biztonságos megoldás kisgyermekes vagy háziállatos háztartásban gyertyagyújtás helyett?', '["Magas polcra tett hagyományos teamécses", "LED-es elemes gyertya vagy mécses használata.", "Illatgyertya nyitott tálkában a szőnyegre vagy az alacsony dohányzóasztalra helyezve."]'::jsonb, 1, 'Egy kíváncsi háziállat egyetlen mozdulattal leverheti az égő gyertyát – a LED-es gyertya teljesen tűzbiztos.', 'advent'),
    ('Használható-e csillagszóró a karácsonyfán vagy az adventi koszorú felett?', '["Igen, nyugodtan felakasztható a fára, ha előtte befújjuk a tűleveleket hajlakkal.", "Nem, az 1000–1600 °C-os szikrák azonnal lángra lobbantják a száraz fát.", "Igen, egyszerre akár több csillagszóró is meggyújtható a száraz fenyőágak között."]'::jsonb, 1, 'A csillagszóró szikrája rendkívül forró, a száraz fenyőág pedig szinte robbanásszerűen, másodpercek alatt lángra kap tőle.', 'advent'),
    ('Hogyan kell elhelyezni a karácsonyfát a lakásban tűzvédelmi szempontból?', '["Közvetlenül a forró radiátor, cserépkályha vagy a bejárati ajtó elé állítva.", "Hőforrástól (kályhától, radiátortól) és menekülési útvonaltól (bejárati ajtótól) távol", "Az egyetlen kijárat elé helyezve, több egymásba dugott elosztóval körbevezetve."]'::jsonb, 1, 'A fűtőtestek kiszárítják a fát, ami így sokkal gyúlékonyabbá válik; az ajtó közelében álló égő fa pedig elzárhatja a menekülési utat.', 'advent'),
    ('Mit ne tegyél SOHA, ha a konyhában az ünnepi sütés-főzés közben meggyullad a forró olaj a serpenyőben?', '["Soha ne önts rá vizet!", "Ne tegyél rá fém fedőt", "Ne zárd el alatta a gázt vagy a főzőlapot, amíg a láng magától el nem alszik!"]'::jsonb, 0, 'A víz az égő olajba öntve azonnal gőzzé válik, és hatalmas tűzgömbként szétveti a lángoló zsiradékot – fedővel kell elfojtani.', 'advent'),
    ('Mit jelent a meteorológiai szolgálat által kiadott „vörös” (harmadfokú) riasztás hófúvás vagy ónos eső esetén?', '["Kizárólag a 7,5 tonna feletti tehergépjárművek számára korlátozza az előzést az utakon.", "Halaszthatatlan eseten kívül senki ne induljon útnak: életveszélyes.", "Csak annyit jelent, hogy a hegyvidéki szakaszokon ajánlott a téli szélvédőmosó használata."]'::jsonb, 1, 'A legmagasabb, piros fokozatú riasztásnál a közlekedési infrastruktúra megbénulhat, és az elakadt járművek mentése is akadályozott.', 'teli_idojaras'),
    ('Mit tegyél elsőként, ha autóddal hótorlaszban elakadsz a lakott területen kívül?', '["Indulj el gyalog a hóviharban a legközelebbi falu felé", "Maradj a járműben, kapcsold be a vészvillogót, és hívd a 112-t", "Engedd le a gumiabroncsok nyomását"]'::jsonb, 1, 'A jármű védelmet nyújt a szél és a kihűlés ellen, és a mentőegységek is sokkal könnyebben megtalálják, mint egy gyalogost a hóviharban.', 'teli_idojaras'),
    ('Mire kell kiemelten figyelni, ha a hóban elakadt autóban járatod a motort a fűtés miatt?', '["Semmire, a modern autók teljesen biztonságosak", "Tisztítsd meg a kipufogót a hótól, és résnyire húzd le az ablakot.", "Zárd fel szorosan az összes ablakot, és kapcsold be folyamatosan a belső keringtetést."]'::jsonb, 1, 'A hóval eltömődött kipufogóból a szén-monoxid visszaáramlik az utastérbe, ami percek alatt halálos mérgezést okozhat.', 'teli_idojaras'),
    ('Milyen alapvető felszerelést érdemes télen az autóban tartani egy váratlan elakadás esetére?', '["Elegendő egy vékony műanyag jégkaparó és egy kis flakon illatosított utastér-tisztító.", "Meleg takarót, pót-ruhát, lámpát, powerbankot, vizet és élelmet.", "Csak nyári keréknyomásmérőt, napellenzőt és egy üres műanyag kannát a csomagtartóban."]'::jsonb, 1, 'Hótorlasz vagy útlezárás esetén akár órákat is várakozni kell a mentésre, amikor a testhő megtartása és a telefon feltöltöttsége életmentő.', 'teli_idojaras'),
    ('Mit jelent a szociális ellátórendszerben elrendelt „Vörös kód”?', '["Országos tervszerű áramszünetet jelent a nagyfeszültségű távvezetékek jegesedése miatt.", "Extrém hideg miatt minden szociális intézmény köteles befogadni a hajléktalan vagy bajba jutott embereket", "Teljes körű tüzelési tilalmat rendel el a családi házak vegyestüzelésű kazánjaira."]'::jsonb, 1, 'A Vörös kód figyelmezteti a társadalmat a rendkívüli hidegre, és kötelezővé teszi a krízisellátást minden fenntartó számára.', 'teli_idojaras'),
    ('Mi a helyes teendő, ha közterületen egy kihűlés veszélyének kitett, magatehetetlen embert látsz?', '["Adj neki alkoholt, hogy átmelegedjen", "Hívd a 112-t, és maradj mellette a mentők kiérkezéséig.", "Dörzsöld be erősen fagyott hóval az arcát és a végtagjait a keringés serkentésére."]'::jsonb, 1, 'Az alkohol tágítja a perifériás ereket, így valójában gyorsítja a test hővesztését és a kihűlést.', 'teli_idojaras'),
    ('Mi a legfontosabb szabály, ha befagyott természetes víz (tó, folyó, csatorna) jegére lépnél?', '["Ha a part mentén 2–3 centiméteresnek látszik a jégréteg, bárhol biztonságosan korcsolyázhatsz.", "Csak kijelölt helyen és nappal menj jégre; folyóvíz jegére soha.", "Minél nagyobb csoportban, szorosan egymás mellett haladva menj rá a természetes folyóvízre."]'::jsonb, 1, 'A folyók és csatornák jege az áramlás miatt kiszámíthatatlanul vékonyodik, és a jég alá szorulás szinte azonnal végzetes.', 'teli_idojaras'),
    ('Mit tegyél, ha beszakad alattad a jég?', '["Kapálózz erőteljesen függőleges testhelyzetben, és könyökkel törd magad előtt a vékony jeget.", "Hasalj rá a jégre, terjeszd szét a súlyodat, és hason csúszva kússz vissza arra, amerről jöttél", "Merülj a jégpáncél alá, és a víz alatt úszva próbálj meg egy másik kijáratot keresni."]'::jsonb, 1, 'A jég széle letörik, ha függőlegesen próbálsz kimászni; hason fekve oszlik el a testsúly, és arra a legbiztosabb a jég, amerre korábban elbírt.', 'teli_idojaras'),
    ('Hogyan közlekedj gyalogosan és autóval ónos eső idején?', '["A megszokott sebességgel, csak nagyobb követési távolsággal", "Csak végszükség esetén indulj el, rendkívül lassan és óvatosan.", "Kerékpárral vagy elektromos rollerrel közlekedj, mert két keréken kisebb a megcsúszás esélye."]'::jsonb, 1, 'Az ónos eső azonnal tükörjéggé fagy a hideg burkolaton, amin a járművek irányíthatatlanná válnak.', 'teli_idojaras'),
    ('Hogyan előzheted meg a vízvezetékek elfagyását fűtetlen nyaralóban vagy melléképületben?', '["Hagyj felkapcsolva egy kis teljesítményű LED-lámpát a pincében egész télre fűtés helyett.", "Zárd el a főcsapot, és víztelenítsd a teljes csőhálózatot és a bojlert.", "Tekerd körbe vékony selyempapírral a kerti csapot, miközben nyomás alatt hagyod a rendszert."]'::jsonb, 1, 'A megfagyó víz térfogata megnő, így szétrepeszti a csöveket és a szerelvényeket, ami olvadáskor súlyos vízkárt okoz.', 'teli_idojaras'),
    ('Mi a különbség a hagyományos folyami árvíz és a villámárvíz között?', '["Csak elnevezésbeli különbség van, mindkettő hetek alatt, lassan emelkedő síkvidéki áradás.", "A villámárvíz heves felhőszakadás után percek vagy órák alatt, előjelzés nélkül csap le, főleg domb- és hegyvidéken", "A villámárvíz kizárólag a téli hóolvadáskor, nagy folyók alsó szakaszán alakulhat ki."]'::jsonb, 1, 'A villámárvizek rendkívül gyors lefolyásúak és nagy sodrásúak, ezért a menekülésre és a védekezésre csupán percek állnak rendelkezésre.', 'arviz_belviz'),
    ('Milyen magasságú vízborítás képes már elsodorni egy felnőtt embert áramló árvíz esetén?', '["Csak a mellkasig érő víz", "Már 15–20 cm-es gyors folyású víz is elsodorhat.", "Áramló vízben csak akkor veszélyes a gyaloglás, ha a vízszint meghaladja a vállmagasságot."]'::jsonb, 1, 'A mozgó víztömeg ereje hatalmas: már bokáig-lábszárközépig érő sodrás is könnyen elsodor egy felnőttet.', 'arviz_belviz'),
    ('Mikor válik irányíthatatlanná és sodródik el egy személyautó elárasztott útszakaszon?', '["Csak akkor úszik fel az autó, ha a vízszint már teljesen ellepi a szélvédőt és a motorháztetőt.", "Már 30–50 cm-es áramló víz felúsztatja és elsodorja az autót.", "Egy személygépkocsi több mint egytonnás tömege miatt semmilyen áradásban nem sodródhat el."]'::jsonb, 1, 'Soha ne hajts be elárasztott útszakaszra vagy aluljáróba: az úttest alámosódhat, a felhajtóerő pedig felemeli az autót.', 'arviz_belviz'),
    ('Mi az elsődleges teendő az épület közműveivel, ha az ingatlant árvíz vagy betörő belvíz fenyegeti?', '["Minden lámpát fel kell kapcsolni, hogy jól lássunk", "Áramtalanítani kell a főkapcsolónál, valamint el kell zárni a gáz- és vízcsapot", "Be kell kapcsolni a szivattyút a víz alatt álló pincében"]'::jsonb, 1, 'A víz és az elektromosság találkozása életveszélyes áramütést okoz; áramtalanítás előtt tilos a vízbe lépni.', 'arviz_belviz'),
    ('Hogyan kell helyesen rakni a homokzsákokat védmű építésekor?', '["Függőlegesen egymás mellé állítva", "Kötésben (mint a téglafalat), kb. kétharmadig töltve, a szájukat behajtva és megtaposva.", "Töltsd meg őket színültig száraz kaviccsal, és kötözés nélkül dobáld egymás tetejére."]'::jsonb, 1, 'A kötésben rakott, kb. kétharmadig töltött és jól tömörített zsákok zárnak vízzáróan, és nem csúsznak szét a víznyomás alatt.', 'arviz_belviz'),
    ('Miért veszélyes az árvíz levonulása után azonnal visszatérni a megrongálódott épületbe hatósági engedély nélkül?', '["Csak azért kellemetlen, mert a nedves burkolatok felszáradása több napot is igénybe vehet.", "Az átázott falak statikailag meggyengülhettek, és fertőző szennyvíz maradhatott.", "Mert a levonuló ár után az épületekben átmenetileg gyengébb lehet a mobiltelefon-térerő."]'::jsonb, 1, 'A víz alámoshatja az alapozást és a közművezetékeket; a visszaköltözést statikai és közegészségügyi ellenőrzésnek kell megelőznie.', 'arviz_belviz'),
    ('Mit tegyél az ivóvízzel és az élelmiszerekkel elöntéssel érintett területen?', '["Nyugodtan fogyasztható a vezetékes csapvíz és az ásott kút vize mindenféle forralás nélkül.", "Csak palackozott vagy hatóságilag bevizsgált ivóvizet fogyassz, és dobd ki az árvízzel érintkezett élelmiszert", "Az árvízzel érintkezett kerti zöldségeket és felbontott élelmiszereket elég hideg vízzel leöblíteni."]'::jsonb, 1, 'Az árvíz emésztőgödröket és vegyszertárolókat is elönthet, így a vezetékes és kútvíz is súlyosan szennyeződhet.', 'arviz_belviz'),
    ('Hogyan védekezhetsz otthonodban a csatornarendszeren keresztül visszatorlódó szennyvíz ellen árvíz idején?', '["Semmit nem lehet tenni", "Visszacsapó szeleppel, illetve az összefolyók lezárásával és lesúlyozásával.", "Sajnos semmilyen műszaki vagy ideiglenes védekezési módszer nem létezik visszatorlódás ellen."]'::jsonb, 1, 'A megemelkedett vízszint a csatornahálózaton át a pincékben és földszinti helyiségekben törhet fel, ha nincs visszacsapó szelep.', 'arviz_belviz'),
    ('Mit vigyél magaddal mindenképp, ha a hatóságok elrendelik a lakóhelyed kitelepítését (evakuálását)?', '["Elsősorban a nagyméretű televíziót, a mikrohullámú sütőt és a kerti szerszámkészletet.", "Okmányokat, szedett gyógyszereket, vizet, meleg ruhát és töltött telefont.", "Semmit nem szabad összekészíteni, elegendő egy szál nyári ruhában, iratok nélkül elindulni."]'::jsonb, 1, 'A kész előre összekészített vészhelyzeti csomag (túlélőcsomag) percekkel rövidíti le az elindulást, és biztosítja az ellátást a befogadóhelyen.', 'arviz_belviz'),
    ('Mi a belvíz fő jellemzője és kialakulásának oka?', '["Hirtelen lezúduló hegyvidéki sárlavina, amely sziklákat és kidőlt fákat sodor a völgybe.", "Síkvidéki területeken a telített talaj, az olvadó hó és a csapadék miatt a felszínen összegyűlő, elszivárogni nem tudó víz", "A folyók felső szakaszán kialakuló jégtorlasz, amely percek alatt átszakítja a magaspartot."]'::jsonb, 1, 'A belvíz lassabban alakul ki, mint a villámárvíz, de hetekig tartó elöntéssel áztatja alá az épületeket és teszi tönkre a termést.', 'arviz_belviz'),
    ('Szabad-e belterületen (kertben) avart és kerti zöldhulladékot égetni Magyarországon?', '["Igen, bármikor korlátozás nélkül", "Alapesetben tilos; csak ott szabad, ahol önkormányzati rendelet engedélyezi.", "Minden hétvégén és munkaszüneti napon sötétedés után külön engedély nélkül is megengedett."]'::jsonb, 1, 'Az országos szabályozás tiltja a belterületi avarégetést; kizárólag ott és akkor szabad, ahol ezt helyi önkormányzati rendelet szabályozza.', 'szabadteri_tuz'),
    ('Mit jelent az Országos Tűzgyújtási Tilalom elrendelése?', '["Kizárólag a belvárosi társasházak erkélyén történő elektromos grillezést tiltja meg.", "Erdőkben és 200 méteres körzetükben még a kijelölt tűzrakóhelyen is tilos tüzet gyújtani.", "A kijelölt erdei szalonnasütő helyeken ilyenkor is korlátozás nélkül szabad tüzet rakni."]'::jsonb, 1, 'Fokozott tűzveszély idején a kijelölt erdei tűzrakóhelyek használata is szigorúan tilos a száraz aljnövényzet miatt.', 'szabadteri_tuz'),
    ('Mekkora bírsággal sújtható, aki megszegi a tűzgyújtási tilalmat vagy gondatlanságból szabadtéri tüzet okoz?', '["Csak szóbeli figyelmeztetés jár érte", "Akár 100 000 és 3 000 000 Ft közötti tűzvédelmi bírsággal, plusz a tűzoltás költségeivel", "Egységesen legfeljebb 5 000 forintos helyszíni bírsággal, egyéb költségtérítés nélkül."]'::jsonb, 1, 'A szabadtéri tüzek hatalmas természeti és anyagi kárt okoznak, ezért a hatóság magas bírságot szab ki, és behajtja a vonulási költségeket is.', 'szabadteri_tuz'),
    ('Mire kell figyelni, ha a saját kertedben grillezel vagy bográcsozol?', '["Elég, ha a tűz meggyújtása után bemész a házba", "Ne hagyd őrizetlenül a tüzet, és legyen kéznél oltóanyag (víz, slag, homok).", "Erős, viharos szélben érdemes begyújtani a faszenet, mert a huzat gyorsabban izzítja át."]'::jsonb, 1, 'Egyetlen hirtelen széllökés is parazsat fújhat a száraz fűbe vagy a szomszédos tujasorba – az azonnali oltóanyag életmentő.', 'szabadteri_tuz'),
    ('Hogyan kell helyesen eloltani a szabadtéri tüzet a program végén?', '["Szórj a még izzó parázsra száraz faleveleket és gallyakat, majd hagyd ott a tűzrakóhelyet.", "Bő vízzel vagy földdel teljesen le kell hűteni a parazsat, amíg nem füstöl.", "Hagyd szabadon parázslani éjszakára, mert a hajnali harmat minden esetben magától eloltja."]'::jsonb, 1, 'A hamu alatt megbújó parázs órákkal később, a szél feltámadásával újra lángra lobbanhat.', 'szabadteri_tuz'),
    ('Miért különösen veszélyes a tavaszi száraz fű és nádas felgyújtása (tarlóégetés)?', '["Csak esztétikai problémát okoz, mert a fekete pernye összekoszolja a kerti bútorokat.", "A száraz növényzetben a tűz futótűzként, akár 30–40 km/h sebességgel terjed, és pillanatok alatt elérheti a lakóházakat és erdőket", "Hasznos eljárás, mert elpusztítja a kártevőket és semmilyen veszélyt nem jelent a környezetre."]'::jsonb, 1, 'A tarló- és nádaségetés tilos és életveszélyes: a szélirány megváltozása a tűzgyújtót is körbezárhatja.', 'szabadteri_tuz'),
    ('Miért okozhat erdőtüzet egy eldobott üvegpalack vagy üvegszilánk a természetben?', '["Mert megvágja az állatokat", "A napsugarakat gyújtólencseként összegyűjtve meggyújtja a száraz avart.", "Mert az esővízzel érintkező üvegszilánk hőtermelő kémiai reakcióba lép a termőtalajjal."]'::jsonb, 1, 'Az üvegben megtörő napfény könnyedén eléri a száraz levelek és fűszálak gyulladási hőmérsékletét.', 'szabadteri_tuz'),
    ('Hogyan szabad megszabadulni a cigarettacsikktől autóban vagy kirándulás közben?', '["Kidobhatod az autó ablakán menet közben, mert a menetszél azonnal eloltja a parazsat.", "Csak teljesen elnyomva, zárt hamutartóban; a természetben soha ne dobd el.", "Erdőszélen elegendő száraz fűcsomóba ejteni és egyetlen gyors mozdulattal rálépni."]'::jsonb, 1, 'Az út menti száraz gaz és az erdei avar az eldobott, még parázsló csikkektől gyullad meg leggyakrabban.', 'szabadteri_tuz'),
    ('Mit tegyél azonnal, ha szabadtéri tüzet (füstöt vagy lángokat) észlelsz a határban vagy az erdőben?', '["Szaladj a lángok elé szélirányba, hogy közelről készíthess felvételt a közösségi oldalakra.", "Távolodj el biztonságos irányba (széliránnyal szemben vagy oldalirányba), és azonnal hívd a 112-t a pontos helyszín megadásával", "Próbáld meg egyedül, kabáttal csapkodva megállítani a gyorsan terjedő magas lángfalat."]'::jsonb, 1, 'A gyors jelzés kulcsfontosságú, hogy a tűzoltók még a tűz továbbterjedése előtt beavatkozhassanak.', 'szabadteri_tuz'),
    ('Hogyan teheted tűzbiztosabbá a házad környékét tavasszal és nyáron?', '["Tárolj száraz tűzifát közvetlenül a terasz alatt.", "Nyírd a füvet, és távolítsd el a száraz ágakat, avart a ház körül és az ereszből.", "Hagyd megnőni a derékig érő száraz gazt a kerítés mentén, mert az felfogja a szálló pernyét."]'::jsonb, 1, 'Az épület körüli védőzóna megakadályozza, hogy egy esetleges szomszédos vegetációtűz átterjedjen a tetőszerkezetre.', 'szabadteri_tuz')
) AS b(question, options, correct_index, explanation, category)
WHERE NOT EXISTS (
  SELECT 1 FROM public.quiz_questions q WHERE q.question = b.question
);

NOTIFY pgrst, 'reload schema';

COMMIT;
